export function extensionOf(name: string): string | null {
  const clean = name.split(/[?#]/)[0];
  const base = clean.split("/").pop() ?? clean;
  const dot = base.lastIndexOf(".");
  return dot > 0 ? base.slice(dot + 1).toLowerCase() : null;
}

export function extractName(url: string): string {
  const clean = url.split(/[?#]/)[0];
  return clean.split("/").pop() || "file";
}

export function detectCategory(
  fileName: string,
  mimeType?: string,
): FileCategory {
  const ext = extensionOf(fileName);
  if (ext && EXTENSION_CATEGORY[ext]) return EXTENSION_CATEGORY[ext];
  if (mimeType) {
    const fromMime = categoryFromMime(mimeType);
    if (fromMime) return fromMime;
  }
  return "unsupported";
}

export function resolveViewerDescriptor({
  source,
  category,
}: {
  source: ViewerSource;
  category?: FileCategory;
}): ViewerDescriptor {
  const resolvedMimeType =
    source.mimeType ??
    (source.kind === "blob" && source.blob.type ? source.blob.type : undefined);
  const displayName = source.fileName ?? defaultDisplayName(source);
  const fileName = source.fileName ?? defaultFileName(source);
  const resolvedCategory =
    category ?? detectCategory(displayName, resolvedMimeType);

  return {
    source,
    category: resolvedCategory,
    identityKey: source.identityKey ?? defaultIdentityKey(source),
    displayName,
    fileName,
    mimeType: resolvedMimeType,
  };
}

function categoryFromMime(mimeType: string): FileCategory | null {
  const mime = mimeType.toLowerCase().split(";")[0].trim();
  if (mime === "application/pdf") return "pdf";
  if (mime.includes("wordprocessingml")) return "docx";
  if (mime.includes("spreadsheet") || mime.includes("ms-excel")) return "xlsx";
  if (mime.includes("presentation") || mime.includes("ms-powerpoint")) {
    return "pptx";
  }
  if (mime === "text/csv" || mime === "text/tab-separated-values") return "csv";
  if (mime === "text/markdown") return "markdown";
  if (mime === "text/html") return "html";
  if (mime === "message/rfc822" || mime === "message/global") {
    return "email";
  }
  if (mime.startsWith("image/")) return "image";
  if (mime === "application/json" || mime === "application/xml") return "text";
  if (mime.startsWith("text/")) return "text";
  return null;
}

function defaultDisplayName(source: ViewerSource) {
  if (source.kind === "url") return source.url;
  if (source.kind === "text") return "text.txt";
  return "file";
}

function defaultFileName(source: ViewerSource) {
  if (source.kind === "url") return extractName(source.url);
  if (source.kind === "text") return "text.txt";
  return "file";
}

function defaultIdentityKey(source: ViewerSource) {
  if (source.kind === "url") return `url:${source.url}`;
  if (source.kind === "text") return textPayloadIdentityKey(source.text);
  return source.identityKey;
}

export function textPayloadIdentityKey(text: string) {
  return textPayloadKey(text);
}

export function textPayloadKey(text: string) {
  return `text:${text.length}:${hashString(text)}`;
}

function hashString(text: string) {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(36);
}

import {
  createBlobDownloadAction,
  createHrefDownloadAction,
  createTextDownloadAction,
  type ViewerDownloadAction,
} from "@/lib/viewer-download-actions";
import {
  isAbortError,
  ResourceError,
  type ResourceTooLargeReason,
} from "@/lib/viewer-errors";
import {
  resolveViewerDescriptor,
  textPayloadKey,
  type BlobViewerSource,
  type FileCategory,
  type TextSource,
  type UrlViewerSource,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source";

export interface ResourceReadOptions {
  cache?: RequestCache;
  signal?: AbortSignal;
}

export interface TextReadOptions extends ResourceReadOptions {
  maxBytes?: number;
  maxLines?: number;
}

export interface ByteRange {
  start: number;
  end: number;
}

export interface ByteRangeResult {
  buffer: ArrayBuffer;
  contentRange?: {
    start: number;
    end: number;
    total: number | null;
  };
  isComplete: boolean;
}

export interface ViewerResourceKeys {
  readonly load: string;
  readonly presentation: string;
  readonly resource: string;
}

export type ViewerResourcePayload =
  | { kind: "url"; url: string }
  | { kind: "blob"; blob: Blob }
  | { kind: "text"; text: string };

export interface ViewerResourceContent {
  readonly key: string;
  readonly sourceKind: ViewerSource["kind"];
  readonly directUrl: string | null;
  readonly mimeType?: string;
  readonly payload: ViewerResourcePayload;
  readBlob(options?: ResourceReadOptions): Promise<Blob>;
  readBytes(options?: ResourceReadOptions): Promise<ArrayBuffer>;
  readText(options?: TextReadOptions): Promise<string>;
  readStream(
    options?: ResourceReadOptions,
  ): Promise<ReadableStream<Uint8Array>>;
  readRange(
    range: ByteRange,
    options?: ResourceReadOptions,
  ): Promise<ByteRangeResult>;
}

export type ViewerContentIdentity = Pick<
  ViewerResourceContent,
  "key" | "sourceKind"
>;

export type ViewerContentDirectUrl = ViewerContentIdentity &
  Pick<ViewerResourceContent, "directUrl">;

export type ViewerContentPayload = ViewerContentIdentity &
  Pick<ViewerResourceContent, "payload">;

export type ViewerContentMime = ViewerContentIdentity &
  Pick<ViewerResourceContent, "mimeType">;

export type ViewerContentBlob = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readBlob">;

export type ViewerContentBytes = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readBytes">;

export type ViewerContentText = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readText">;

export type ViewerContentStream = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readStream">;

export type ViewerContentRange = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readRange">;

export interface ViewerResource {
  readonly descriptor: ViewerDescriptor;
  readonly sourceKind: ViewerSource["kind"];
  readonly keys: ViewerResourceKeys;
  readonly identityKey: string;
  readonly fileName: string;
  readonly mimeType?: string;
  readonly content: ViewerResourceContent;
  readonly originalDownload: ViewerDownloadAction;
}

const URL_RESOURCE_REGISTRY_MAX = 128;
const TEXT_RESOURCE_REGISTRY_MAX = 64;
// LF, CR, CRLF, LINE SEPARATOR (U+2028), and PARAGRAPH SEPARATOR (U+2029) — the
// ECMAScript LineTerminator set, matching what a browser breaks on in a
// `white-space: pre` block. Kept in sync with text-viewer-resource's splitter.
const TEXT_LINE_BREAK_PATTERN = /\r\n|[\n\r\u2028\u2029]/g;

const urlViewerResourceRegistry = new Map<string, ViewerResource>();
const urlViewerResourceContentRegistry = new Map<
  string,
  ViewerResourceContent
>();
const textViewerResourceRegistry = new Map<string, ViewerResource>();
const textViewerResourceContentRegistry = new Map<
  string,
  ViewerResourceContent
>();
let blobViewerResourceRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResource>
>();
let blobViewerResourceContentRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResourceContent>
>();
const blobObjectKeys = new WeakMap<Blob, string>();
let nextBlobObjectKey = 0;

export function createViewerResource(
  source: ViewerSource,
  category?: FileCategory,
): ViewerResource {
  const descriptor = resolveViewerDescriptor({ source, category });
  const keys = viewerResourceKeys(source, descriptor);

  if (source.kind === "url") {
    return internUrlResource(source, descriptor, keys);
  }
  if (source.kind === "blob") {
    return internBlobResource(source, descriptor, keys);
  }
  return internTextResource(source, descriptor, keys);
}

export function clearViewerResourceRegistryForTests() {
  urlViewerResourceRegistry.clear();
  urlViewerResourceContentRegistry.clear();
  textViewerResourceRegistry.clear();
  textViewerResourceContentRegistry.clear();
  blobViewerResourceRegistry = new WeakMap();
  blobViewerResourceContentRegistry = new WeakMap();
}

function internUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
): ViewerResource {
  const cached = urlViewerResourceRegistry.get(keys.resource);
  if (cached) return cached;

  const resource = createUrlResource(source, descriptor, keys);
  urlViewerResourceRegistry.set(keys.resource, resource);
  pruneUrlResourceRegistry();
  return resource;
}

function internBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
): ViewerResource {
  let resources = blobViewerResourceRegistry.get(source.blob);
  if (!resources) {
    resources = new Map();
    blobViewerResourceRegistry.set(source.blob, resources);
  }

  const cached = resources.get(keys.resource);
  if (cached) return cached;

  const resource = createBlobResource(source, descriptor, keys);
  resources.set(keys.resource, resource);
  return resource;
}

function internTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
): ViewerResource {
  const cached = textViewerResourceRegistry.get(keys.resource);
  if (cached) return cached;

  const resource = createTextResource(source, descriptor, keys);
  textViewerResourceRegistry.set(keys.resource, resource);
  pruneTextResourceRegistry();
  return resource;
}

function pruneUrlResourceRegistry() {
  while (urlViewerResourceRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceRegistry.keys().next().value;
    if (!firstKey) return;
    urlViewerResourceRegistry.delete(firstKey);
  }
}

function pruneUrlResourceContentRegistry() {
  while (urlViewerResourceContentRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceContentRegistry.keys().next().value;
    if (!firstKey) return;
    urlViewerResourceContentRegistry.delete(firstKey);
  }
}

function pruneTextResourceRegistry() {
  while (textViewerResourceRegistry.size > TEXT_RESOURCE_REGISTRY_MAX) {
    const firstKey = textViewerResourceRegistry.keys().next().value;
    if (!firstKey) return;
    textViewerResourceRegistry.delete(firstKey);
  }
}

function pruneTextResourceContentRegistry() {
  while (textViewerResourceContentRegistry.size > TEXT_RESOURCE_REGISTRY_MAX) {
    const firstKey = textViewerResourceContentRegistry.keys().next().value;
    if (!firstKey) return;
    textViewerResourceContentRegistry.delete(firstKey);
  }
}

function viewerResourceKeys(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
): ViewerResourceKeys {
  const load = viewerResourceLoadKey(source, descriptor);
  const presentation = viewerResourcePresentationKey(source, descriptor);
  return {
    load,
    presentation,
    resource: [load, presentation].join("\u0000"),
  };
}

function viewerResourceLoadKey(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
) {
  return [
    source.kind,
    source.identityKey ?? "",
    sourceMimeType(source) ?? "",
    directLoadCacheKey(source),
    payloadCacheKey(source, descriptor),
  ].join("\u0000");
}

function viewerResourcePresentationKey(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
) {
  return [
    descriptor.category,
    descriptor.displayName,
    descriptor.fileName,
    descriptor.mimeType ?? "",
    downloadCacheKey(source),
  ].join("\u0000");
}

function directLoadCacheKey(source: ViewerSource) {
  return source.kind === "url" ? source.url : "";
}

function downloadCacheKey(source: ViewerSource) {
  if (source.kind === "text") return "";
  return source.downloadUrl ?? "";
}

function payloadCacheKey(source: ViewerSource, descriptor: ViewerDescriptor) {
  if (source.kind === "url") return "";
  if (source.kind === "blob") return blobObjectKey(source.blob);
  return source.identityKey ? "" : descriptor.identityKey;
}

export function viewerResourceRenderKey(resource: ViewerResource): string {
  const load = [
    resource.sourceKind,
    resource.identityKey,
    resource.mimeType ?? resource.content.mimeType ?? "",
    resource.content.directUrl ?? "",
    viewerContentRenderKey(resource.content),
  ].join("\u0000");

  return [load, resource.keys.presentation].join("\u0000");
}

export function viewerContentRenderKey(content: ViewerResourceContent): string {
  if (content.payload.kind === "text")
    return textPayloadKey(content.payload.text);
  return content.key;
}

function sourceMimeType(source: ViewerSource) {
  if (source.kind === "blob") return source.mimeType ?? source.blob.type;
  return source.mimeType;
}

function blobObjectKey(blob: Blob) {
  let key = blobObjectKeys.get(blob);
  if (!key) {
    nextBlobObjectKey += 1;
    key = `blob-object:${nextBlobObjectKey}`;
    blobObjectKeys.set(blob, key);
  }
  return key;
}

export function blobSource(
  bytes: Blob | ArrayBuffer | Uint8Array,
  metadata: {
    identityKey: string;
    fileName?: string;
    mimeType?: string;
    downloadUrl?: string;
  },
): BlobViewerSource {
  const blob =
    bytes instanceof Blob
      ? bytes
      : new Blob(
          [bytes instanceof ArrayBuffer ? bytes : new Uint8Array(bytes)],
          {
            type: metadata.mimeType ?? "",
          },
        );
  return {
    kind: "blob",
    blob,
    fileName: metadata.fileName,
    mimeType: metadata.mimeType ?? blob.type,
    downloadUrl: metadata.downloadUrl,
    identityKey: metadata.identityKey,
  };
}

function createUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
): ViewerResource {
  const content = internUrlResourceContent(source, keys);
  const originalDownload = createHrefDownloadAction({
    id: "download-original",
    label: "Download",
    href: source.downloadUrl ?? source.url,
    fileName: descriptor.fileName,
  });

  return resourceBase(source, descriptor, keys, { content, originalDownload });
}

function internUrlResourceContent(
  source: UrlViewerSource,
  keys: ViewerResourceKeys,
): ViewerResourceContent {
  const cached = urlViewerResourceContentRegistry.get(keys.load);
  if (cached) return cached;

  const content = resourceContentBase(source, keys, {
    directUrl: source.url,
    payload: { kind: "url", url: source.url },
    readBlob: async ({ cache, signal } = {}) => {
      const response = await fetchResource(
        source.url,
        cache ? { cache, signal } : { signal },
      );
      validateFullContentResponse(response);
      return readResponseBlob(response);
    },
    readBytes: async ({ cache, signal } = {}) => {
      const response = await fetchResource(
        source.url,
        cache ? { cache, signal } : { signal },
      );
      validateFullContentResponse(response);
      return readResponseArrayBuffer(response);
    },
    readText: async ({ cache, signal, maxBytes, maxLines } = {}) => {
      const response = await fetchResource(
        source.url,
        cache ? { cache, signal } : { signal },
      );
      return readBoundedResponseText(response, { maxBytes, maxLines });
    },
    readStream: async ({ cache, signal } = {}) => {
      const response = await fetchResource(
        source.url,
        cache ? { cache, signal } : { signal },
      );
      validateFullContentResponse(response);
      if (!response.body) {
        if (response.status === 204 || response.status === 205) {
          return emptyByteStream();
        }
        throw new ResourceError({
          kind: "unsupported_capability",
          message: "This response cannot be streamed.",
        });
      }
      return response.body;
    },
    readRange: async (range, { cache, signal } = {}) => {
      validateByteRange(range);
      const { start, end } = range;
      const init = {
        signal,
        headers: { Range: `bytes=${start}-${end}` },
      };
      const response = await fetchResource(
        source.url,
        cache ? { ...init, cache } : init,
      );
      const buffer = await readResponseArrayBuffer(response);
      const contentRange = parseContentRange(
        response.headers.get("content-range"),
      );
      validateUrlRangeResponse({
        bufferLength: buffer.byteLength,
        contentRange,
        range,
        status: response.status,
      });
      return {
        buffer,
        contentRange,
        isComplete: isByteRangeComplete({
          bufferLength: buffer.byteLength,
          contentRange,
          requestedLength: end - start + 1,
          status: response.status,
        }),
      };
    },
  });
  urlViewerResourceContentRegistry.set(keys.load, content);
  pruneUrlResourceContentRegistry();
  return content;
}

function emptyByteStream() {
  return new ReadableStream<Uint8Array>({
    start(controller) {
      controller.close();
    },
  });
}

function createBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
): ViewerResource {
  const blob = source.blob;
  const content = internBlobResourceContent(source, keys);
  const originalDownload = source.downloadUrl
    ? createHrefDownloadAction({
        id: "download-original",
        label: "Download",
        href: source.downloadUrl,
        fileName: descriptor.fileName,
      })
    : createBlobDownloadAction({
        id: "download-original",
        label: "Download",
        blob,
        fileName: descriptor.fileName,
      });

  return resourceBase(source, descriptor, keys, { content, originalDownload });
}

function internBlobResourceContent(
  source: BlobViewerSource,
  keys: ViewerResourceKeys,
): ViewerResourceContent {
  const blob = source.blob;
  let contents = blobViewerResourceContentRegistry.get(blob);
  if (!contents) {
    contents = new Map();
    blobViewerResourceContentRegistry.set(blob, contents);
  }

  const cached = contents.get(keys.load);
  if (cached) return cached;

  const content = resourceContentBase(source, keys, {
    directUrl: null,
    payload: { kind: "blob", blob },
    readBlob: async () => blob,
    readBytes: async () => blob.arrayBuffer(),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedBlobText(blob, { maxBytes, maxLines }),
    readStream: async () => blob.stream(),
    readRange: async (range) => {
      validateByteRange(range);
      const { start, end } = range;
      validateKnownByteRangeStart(start, blob.size);
      const rangeBlob = blob.slice(start, end + 1);
      return {
        buffer: await rangeBlob.arrayBuffer(),
        contentRange: {
          start,
          end: Math.min(end, blob.size - 1),
          total: blob.size,
        },
        isComplete: end >= blob.size - 1,
      };
    },
  });
  contents.set(keys.load, content);
  return content;
}

function createTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
): ViewerResource {
  const content = internTextResourceContent(source, keys);
  const originalDownload = createTextDownloadAction({
    id: "download-original",
    label: "Download",
    text: source.text,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
  });

  return resourceBase(source, descriptor, keys, { content, originalDownload });
}

function internTextResourceContent(
  source: TextSource,
  keys: ViewerResourceKeys,
): ViewerResourceContent {
  const cached = textViewerResourceContentRegistry.get(keys.load);
  if (cached) return cached;

  const content = resourceContentBase(source, keys, {
    directUrl: null,
    payload: { kind: "text", text: source.text },
    readBlob: async () =>
      new Blob([source.text], {
        type: "text/plain;charset=utf-8",
      }),
    readBytes: async () =>
      typedArrayBuffer(new TextEncoder().encode(source.text)),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedInlineText(source.text, { maxBytes, maxLines }),
    readStream: async () => new Blob([source.text]).stream(),
    readRange: async (range) => {
      validateByteRange(range);
      const { start, end } = range;
      const buffer = new TextEncoder().encode(source.text);
      validateKnownByteRangeStart(start, buffer.byteLength);
      const slice = buffer.slice(start, end + 1);
      return {
        buffer: typedArrayBuffer(slice),
        contentRange: {
          start,
          end: Math.min(end, buffer.byteLength - 1),
          total: buffer.byteLength,
        },
        isComplete: end >= buffer.byteLength - 1,
      };
    },
  });
  textViewerResourceContentRegistry.set(keys.load, content);
  pruneTextResourceContentRegistry();
  return content;
}

function resourceBase(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
  options: {
    content: ViewerResourceContent;
    originalDownload: ViewerDownloadAction;
  },
): ViewerResource {
  const { content, originalDownload } = options;
  return Object.freeze({
    descriptor,
    sourceKind: source.kind,
    keys,
    identityKey: descriptor.identityKey,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
    content,
    originalDownload,
  });
}

function resourceContentBase(
  source: ViewerSource,
  keys: ViewerResourceKeys,
  methods: Omit<ViewerResourceContent, "key" | "sourceKind" | "mimeType">,
): ViewerResourceContent {
  return Object.freeze({
    key: keys.load,
    sourceKind: source.kind,
    mimeType: sourceMimeType(source),
    ...methods,
  });
}

function typedArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.buffer.slice(
    bytes.byteOffset,
    bytes.byteOffset + bytes.byteLength,
  ) as ArrayBuffer;
}

async function fetchResource(
  input: RequestInfo | URL,
  init?: RequestInit,
): Promise<Response> {
  let response: Response;
  try {
    response = await fetch(input, init);
  } catch (error) {
    if (isAbortError(error)) {
      throw new ResourceError({
        kind: "aborted",
        message: "Loading was cancelled.",
        cause: error,
      });
    }
    throw new ResourceError({
      kind: "fetch_failed",
      message: "Could not fetch this resource.",
      cause: error,
    });
  }

  if (!response.ok && response.status !== 206) {
    throw new ResourceError({
      kind: "http_error",
      message: `Failed to load resource: ${response.status}`,
      status: response.status,
    });
  }

  return response;
}

async function readBoundedResponseText(
  response: Response,
  bounds: { maxBytes?: number; maxLines?: number },
) {
  validateFullContentResponse(response);

  const maxBytes = bounds.maxBytes;
  if (
    isContentLengthOverLimit(response.headers.get("content-length"), maxBytes)
  ) {
    throw tooLarge("bytes");
  }

  const body = response.body;
  if (!body) {
    const buffer = await readResponseArrayBuffer(response);
    if (maxBytes != null && buffer.byteLength > maxBytes) {
      throw tooLarge("bytes");
    }
    const text = new TextDecoder().decode(buffer);
    assertLineLimit(text, bounds.maxLines);
    return text;
  }

  const reader = body.getReader();
  const decoder = new TextDecoder();
  const lineLimitTracker = createLineLimitTracker(bounds.maxLines);
  let receivedBytes = 0;
  let text = "";

  while (true) {
    const { done, value } = await readResponseStreamChunk(reader);
    if (done) break;
    receivedBytes += value.byteLength;
    if (maxBytes != null && receivedBytes > maxBytes) {
      await cancelReaderSilently(reader);
      throw tooLarge("bytes");
    }
    const chunkText = decoder.decode(value, { stream: true });
    try {
      lineLimitTracker.push(chunkText);
    } catch (error) {
      await cancelReaderSilently(reader);
      throw error;
    }
    text += chunkText;
  }

  const finalText = decoder.decode();
  lineLimitTracker.push(finalText);
  text += finalText;
  return text;
}

function isContentLengthOverLimit(
  contentLength: string | null,
  maxBytes: number | undefined,
) {
  if (maxBytes == null || contentLength == null) return false;

  const normalizedLength = contentLength.trim().replace(/^0+(?=\d)/, "");
  if (!/^\d+$/.test(normalizedLength)) return false;

  const maxLength = String(maxBytes);
  return (
    normalizedLength.length > maxLength.length ||
    (normalizedLength.length === maxLength.length &&
      normalizedLength > maxLength)
  );
}

function validateFullContentResponse(response: Response) {
  if (response.status !== 206) return;

  const contentRange = parseContentRange(response.headers.get("content-range"));
  if (
    contentRange?.total != null &&
    contentRange.start === 0 &&
    contentRange.end === contentRange.total - 1
  ) {
    return;
  }

  throw new ResourceError({
    kind: "partial_content",
    message: "Full response returned partial content.",
    status: response.status,
  });
}

async function readResponseStreamChunk(
  reader: ReadableStreamDefaultReader<Uint8Array>,
) {
  try {
    return await reader.read();
  } catch (error) {
    throw resourceReadError(error);
  }
}

async function readResponseArrayBuffer(response: Response) {
  try {
    return await response.arrayBuffer();
  } catch (error) {
    throw resourceReadError(error);
  }
}

async function readResponseBlob(response: Response) {
  try {
    return await response.blob();
  } catch (error) {
    throw resourceReadError(error);
  }
}

function resourceReadError(error: unknown) {
  if (isAbortError(error)) {
    return new ResourceError({
      kind: "aborted",
      message: "Loading was cancelled.",
      cause: error,
    });
  }
  return new ResourceError({
    kind: "fetch_failed",
    message: "Could not read this resource.",
    cause: error,
  });
}

async function readBoundedBlobText(
  blob: Blob,
  bounds: { maxBytes?: number; maxLines?: number },
) {
  if (bounds.maxBytes != null && blob.size > bounds.maxBytes) {
    throw tooLarge("bytes");
  }
  const text = await blob.text();
  assertLineLimit(text, bounds.maxLines);
  return text;
}

function readBoundedInlineText(
  text: string,
  { maxBytes, maxLines }: { maxBytes?: number; maxLines?: number },
) {
  // For inline sources the string *is* the resource, so its UTF-8 byte length
  // is the authoritative size to measure against maxBytes.
  if (
    maxBytes != null &&
    new TextEncoder().encode(text).byteLength > maxBytes
  ) {
    throw tooLarge("bytes");
  }
  assertLineLimit(text, maxLines);
  return text;
}

// Used after a transferred-byte check has already enforced maxBytes (URL/blob).
// Re-encoding the decoded text here would double-count: invalid UTF-8 decodes to
// U+FFFD (3 bytes each), inflating the measured size past the real wire bytes
// and falsely rejecting small resources as "too large".
function assertLineLimit(text: string, maxLines: number | undefined) {
  if (
    maxLines != null &&
    text.split(TEXT_LINE_BREAK_PATTERN).length > maxLines
  ) {
    throw tooLarge("lines");
  }
}

function tooLarge(reason: ResourceTooLargeReason) {
  return new ResourceError({
    kind: "too_large",
    tooLargeReason: reason,
    message: `Resource exceeds ${reason} limit.`,
  });
}

async function cancelReaderSilently(
  reader: ReadableStreamDefaultReader<Uint8Array>,
) {
  try {
    await reader.cancel();
  } catch {
    // Preserve the user-facing load failure; cancellation is best-effort cleanup.
  }
}

function validateByteRange({ start, end }: ByteRange) {
  if (
    !Number.isSafeInteger(start) ||
    !Number.isSafeInteger(end) ||
    start < 0 ||
    end < start
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range must use non-negative integer bounds.",
    });
  }
}

function validateKnownByteRangeStart(start: number, total: number) {
  if (start > 0 && start >= total) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range starts past the available resource.",
    });
  }
}

function validateUrlRangeResponse({
  bufferLength,
  contentRange,
  range,
  status,
}: {
  bufferLength: number;
  contentRange: ByteRangeResult["contentRange"];
  range: ByteRange;
  status: number;
}) {
  if (status === 200) {
    if (range.start !== 0 || bufferLength > range.end - range.start + 1) {
      throw new ResourceError({
        kind: "invalid_range",
        message: "Full response does not match the requested byte range.",
      });
    }
    return;
  }
  if (status !== 206) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Range response must return full or partial content.",
    });
  }
  if (!contentRange) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Partial content response is missing a valid byte range.",
    });
  }
  const declaredLength = contentRange.end - contentRange.start + 1;
  if (
    contentRange.start !== range.start ||
    contentRange.end < contentRange.start ||
    contentRange.end > range.end ||
    (contentRange.total != null && contentRange.end >= contentRange.total) ||
    declaredLength !== bufferLength
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Response byte range does not match the requested range.",
    });
  }
}

function isByteRangeComplete({
  bufferLength,
  contentRange,
  requestedLength,
  status,
}: {
  bufferLength: number;
  contentRange: ByteRangeResult["contentRange"];
  requestedLength: number;
  status: number;
}) {
  if (status === 200) return true;
  if (contentRange?.total != null) {
    if (contentRange.total <= 0) return true;
    return contentRange.end >= contentRange.total - 1;
  }
  if (contentRange) return false;
  return bufferLength < requestedLength;
}

function isStandaloneLineBreak(character: string) {
  const code = character.charCodeAt(0);
  return code === 0x0a || code === 0x2028 || code === 0x2029;
}

function createLineLimitTracker(maxLines: number | undefined) {
  let lineCount = 1;
  let previousWasCR = false;

  return {
    push(text: string) {
      if (maxLines == null || text.length === 0) return;

      for (const character of text) {
        if (previousWasCR) {
          previousWasCR = false;
          if (character === "\n") continue;
        }

        if (character === "\r") {
          lineCount += 1;
          previousWasCR = true;
        } else if (isStandaloneLineBreak(character)) {
          // LF, plus LINE/PARAGRAPH SEPARATOR (U+2028/U+2029); none pair with CR.
          lineCount += 1;
        }

        if (lineCount > maxLines) {
          throw tooLarge("lines");
        }
      }
    },
  };
}

function parseContentRange(value: string | null) {
  if (!value) return undefined;
  const match = value.match(/^bytes\s+(\d+)-(\d+)\/(\d+|\*)\s*$/i);
  if (!match) return undefined;
  const start = parseContentRangeNumber(match[1]);
  const end = parseContentRangeNumber(match[2]);
  const total =
    match[3] === "*" ? null : parseContentRangeNumber(match[3] ?? "");
  if (start == null || end == null || total === undefined) return undefined;
  return {
    start,
    end,
    total,
  };
}

function parseContentRangeNumber(value: string) {
  const number = Number(value);
  return Number.isSafeInteger(number) ? number : undefined;
}

"use client";

import * as React from "react";
import { Download } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download-actions";

import { Spinner } from "@/components/ui/spinner";

import { Button, buttonVariants } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal;
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions,
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    });
  }

  let payload: ViewerDownloadPayload;
  try {
    payload = await action.getPayload(options);
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      });
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    });
  }

  if (payload.kind === "none") return;
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName);
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      });
    }
    return;
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          });
    const url = URL.createObjectURL(blob);
    try {
      clickDownload(url, action.fileName);
    } finally {
      URL.revokeObjectURL(url);
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    });
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction,
) => void;

export interface ViewerDownloadTrigger {
  pendingActionId: string | null;
  triggerDownload: (action: ViewerDownloadAction) => void;
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler;
  resetKey?: unknown;
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>;
  variant?: React.ComponentProps<typeof Button>["variant"];
  size?: React.ComponentProps<typeof Button>["size"];
  className?: string;
  showLabel?: boolean;
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler;
}

export interface ViewerDownloadButtonProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  action: ViewerDownloadAction | null;
}

export interface ViewerDownloadMenuProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  actions: ViewerDownloadAction[];
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null,
): string | null {
  const shouldCreateHref = action?.origin !== "derived";
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null;

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null;
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null,
  );
  const abortControllerRef = React.useRef<AbortController | null>(null);

  useKeyedMountEffect(joinEffectKey([resetKey]), () => {
    return () => {
      abortControllerRef.current?.abort();
      abortControllerRef.current = null;
    };
  });

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort();
      const abortController = new AbortController();
      abortControllerRef.current = abortController;
      setPendingActionId(action.id);
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError);
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null;
            setPendingActionId(null);
          }
        });
    },
    [onError],
  );

  return { pendingActionId, triggerDownload };
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action),
  );

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    );
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  );
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action);
  const label = action?.label ?? "Download";
  const disabled = !action || action.isDisabled;
  const hasDownloadHref = Boolean(href);
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  });
  const isPending = Boolean(action && pendingActionId === action.id);

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return;
    triggerDownload(action);
  }, [action, hasDownloadHref, triggerDownload]);

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    );
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled || isPending}
      onClick={handleClick}
    >
      {isPending ? (
        <Spinner className="size-4 animate-spin" />
      ) : (
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      )}
      {showLabel ? label : null}
    </Button>
  );
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000");
  const label = "Download";
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  });

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant={variant}
          size={size}
          className={className}
          aria-label={label}
          title={label}
          disabled={pendingActionId != null}
        >
          {pendingActionId != null ? (
            <Spinner className="size-4 animate-spin" />
          ) : (
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
          )}
          {showLabel ? label : null}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a");
  anchor.href = href;
  anchor.download = fileName;
  anchor.rel = "noreferrer";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null,
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null;
  const payload = action.getPayload();
  return payload instanceof Promise ? null : payload;
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined,
) {
  if (!(error instanceof ViewerDownloadError)) return;
  if (error.kind === "aborted") return;
  onError?.(error, action);
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError";
}

export interface PptxSize {
  width: number;
  height: number;
}

export interface PptxSlideOverlayProps {
  /** 1-based slide index. */
  slideNumber: number;
  /** Rendered slide size in CSS pixels, after scale and rotation. */
  width: number;
  height: number;
  scale: number;
  rotation: number;
}

export interface PptxSlideRenderTiming {
  slideNumber: number;
  durationMs: number;
  renderScale: number;
  pixelRatio: number;
  cached: boolean;
  status: "rendered" | "cancelled" | "failed";
}

export interface PptxSourceLoadTiming {
  byteLength: number;
  slideCount: number;
  totalMs: number;
  readBytesMs: number;
  importPptxMs: number;
  readSlideSizeMs: number;
  loadFileMs: number;
  inspectMs: number;
}

export interface PptxResetInput {
  resourceKey: string;
  scale?: number;
  defaultScale?: number;
  eager?: boolean;
}

export interface PptxBitmapCacheInput {
  slideIndex: number;
  renderScale: number;
}

export interface PptxSlideRenderPriority {
  isCurrentSlide: boolean;
  isInViewport: boolean;
  isScrollLead: boolean;
  distanceFromReadingMarker: number;
}

// 16:9 — the modern PowerPoint/Slides default. Used as the pre-parse skeleton
// aspect and as a last-resort fallback when a loaded deck can't report its size.
export const DEFAULT_PPTX_SLIDE_SIZE = {
  width: 960,
  height: 540,
} satisfies PptxSize;

export function getPptxFitScale(
  containerWidth: number | null,
  baseWidth: number,
) {
  if (!containerWidth || !Number.isFinite(containerWidth) || baseWidth <= 0) {
    return 1;
  }
  return clamp((containerWidth - 32) / baseWidth, 0.1, 5);
}

export function getPptxResetKey({
  resourceKey,
  scale,
  defaultScale,
  eager,
}: PptxResetInput) {
  return [
    resourceKey,
    getResetScaleKey({ scale, defaultScale }),
    eager ? "eager" : "settled",
  ].join("\u0000");
}

function getResetScaleKey({
  scale,
  defaultScale,
}: Pick<PptxResetInput, "scale" | "defaultScale">) {
  if (scale !== undefined) return normalizePptxScale(scale);
  if (defaultScale !== undefined) return normalizePptxScale(defaultScale);
  return "fit";
}

export function getPptxBitmapCacheKey({
  slideIndex,
  renderScale,
}: PptxBitmapCacheInput) {
  return `${slideIndex}@${Math.round(renderScale * 1000)}`;
}

export function getPptxRenderPixelRatio(rawPixelRatio: number) {
  if (!Number.isFinite(rawPixelRatio) || rawPixelRatio <= 0) return 1;
  return Math.min(rawPixelRatio, 2);
}

export function getScaledSlideSize(
  baseSize: PptxSize,
  zoomScale: number,
): PptxSize {
  return {
    width: baseSize.width * zoomScale,
    height: baseSize.height * zoomScale,
  };
}

export function getVisibleSlideSize(
  slideSize: PptxSize,
  rotation: number,
): PptxSize {
  return getRotatedSize(slideSize, rotation);
}

export function getRotatedSize(size: PptxSize, rotation: number): PptxSize {
  const normalized = ((rotation % 360) + 360) % 360;
  if (normalized === 90 || normalized === 270) {
    return { width: size.height, height: size.width };
  }
  return size;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function normalizePptxScale(scale: number) {
  return clamp(Number.isFinite(scale) ? scale : 1, 0.1, 5);
}

import { lruGet } from "./viewer-lru-cache";

export interface Disposable {
  dispose(): void;
  /**
   * Optional eviction guard. When it returns false the entry is "pinned" and the
   * LRU will skip it when choosing a victim (evicting the next-oldest evictable
   * entry instead, or temporarily exceeding the limit if every overflow entry is
   * pinned). Undefined is treated as always-evictable.
   */
  isEvictable?(): boolean;
}

export interface DisposableLruBudget<V> {
  maxCost: number;
  getCost(value: V): number;
}

export class DisposableLruCache<K, V extends Disposable> {
  private values = new Map<K, V>();

  constructor(
    private readonly limit: number,
    private readonly budget?: DisposableLruBudget<V>,
  ) {}

  get size() {
    return this.values.size;
  }

  get(key: K): V | undefined {
    return lruGet(this.values, key);
  }

  snapshotValues(): V[] {
    return [...this.values.values()];
  }

  set(key: K, value: V) {
    const existing = this.values.get(key);
    if (existing) existing.dispose();
    this.values.delete(key);
    this.values.set(key, value);
    this.evictExcess();
  }

  private evictExcess() {
    while (this.values.size > this.limit || this.exceedsBudget()) {
      const victim = this.oldestEvictableKey();
      // Every overflow entry is pinned (e.g. still loading); keep them all and
      // let the cache shrink back once they become evictable.
      if (victim === undefined) break;
      const dropped = this.values.get(victim);
      this.values.delete(victim);
      dropped?.dispose();
    }
  }

  private exceedsBudget() {
    return !!this.budget && this.totalCost() > this.budget.maxCost;
  }

  private totalCost() {
    if (!this.budget) return 0;
    let total = 0;
    for (const value of this.values.values()) {
      total += Math.max(0, this.budget.getCost(value));
    }
    return total;
  }

  private oldestEvictableKey(): K | undefined {
    // Map iterates in LRU order (oldest first), so the first evictable entry is
    // the least-recently-used one that is safe to drop.
    for (const [key, value] of this.values) {
      if (value.isEvictable === undefined || value.isEvictable()) return key;
    }
    return undefined;
  }

  delete(key: K) {
    const value = this.values.get(key);
    if (!value) return;
    this.values.delete(key);
    value.dispose();
  }

  clear() {
    for (const value of this.values.values()) value.dispose();
    this.values.clear();
  }
}

export class PptxBitmapEntry implements Disposable {
  constructor(readonly bitmap: ImageBitmap) {}

  get pixelCount() {
    return Math.max(0, this.bitmap.width * this.bitmap.height);
  }

  dispose() {
    this.bitmap.close();
  }
}

export const VIEWER_LRU_CACHE_MAX = 12;

export function lruGet<K, V>(map: Map<K, V>, key: K): V | undefined {
  const value = map.get(key);
  if (value !== undefined) {
    map.delete(key);
    map.set(key, value);
  }
  return value;
}

export function lruSet<K, V>(
  map: Map<K, V>,
  key: K,
  value: V,
  onEvict?: (key: K, value: V) => void,
  max = VIEWER_LRU_CACHE_MAX,
) {
  map.delete(key);
  map.set(key, value);
  while (map.size > max) {
    const oldest = map.keys().next().value as K | undefined;
    if (oldest === undefined) break;
    const dropped = map.get(oldest);
    map.delete(oldest);
    if (dropped !== undefined) onEvict?.(oldest, dropped);
  }
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import {
  type ViewerContentBytes,
  type ViewerContentIdentity,
} from "@/lib/viewer-resource";

import { type PptxSourceLoadTiming } from "./pptx-viewer-core";
import {
  getPptxSource,
  subscribePptxSourceLoadTiming,
  type PptxSource,
} from "./pptx-viewer-source";

const pptxHookSourceKeys = new WeakMap<PptxSource, string>();
let nextPptxHookSourceKey = 1;

/** Retains the cached source for the mounted lifetime of the viewer. */
export function useRetainedPptxSource(
  content: ViewerContentBytes & ViewerContentIdentity,
  onLoadTiming?: (timing: PptxSourceLoadTiming) => void,
): PptxSource {
  const sourcePromise = React.useMemo(() => getPptxSource(content), [content]);
  const source = React.use(sourcePromise);
  const onLoadTimingRef = React.useRef(onLoadTiming);
  onLoadTimingRef.current = onLoadTiming;

  useKeyedMountEffect(getPptxHookSourceKey(source), () => source.retain());
  useKeyedMountEffect(
    onLoadTiming ? `timing:${content.sourceKind}:${content.key}` : null,
    () =>
      subscribePptxSourceLoadTiming(content, (timing) => {
        onLoadTimingRef.current?.(timing);
      }),
  );
  return source;
}

function getPptxHookSourceKey(source: PptxSource) {
  const existingKey = pptxHookSourceKeys.get(source);
  if (existingKey) return existingKey;
  const key = String(nextPptxHookSourceKey);
  nextPptxHookSourceKey += 1;
  pptxHookSourceKeys.set(source, key);
  return key;
}

import type * as PptxNS from "pptxviewjs";

import {
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorKind,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors";
import { type ViewerContentBytes } from "@/lib/viewer-resource";

import {
  DEFAULT_PPTX_SLIDE_SIZE,
  type PptxSize,
  type PptxSourceLoadTiming,
} from "./pptx-viewer-core";

type PptxModule = typeof PptxNS;

export type PptxRendererErrorKind = ViewerFormatErrorKind;

export class PptxRendererError extends ViewerFormatError {
  override readonly kind: PptxRendererErrorKind;

  constructor(kind: PptxRendererErrorKind, message: string, cause?: unknown) {
    super({ format: "pptx", kind, message, cause });
    this.name = "PptxRendererError";
    this.kind = kind;
  }
}

export interface PptxRenderInput {
  slideIndex: number;
  canvas: HTMLCanvasElement;
  renderScale: number;
}

export interface PptxRenderer {
  slideCount: number;
  baseSize: PptxSize;
  renderSlide(input: PptxRenderInput): Promise<void>;
  dispose(): void;
}

let pptxModulePromise: Promise<PptxModule> | null = null;

function loadPptx(): Promise<PptxModule> {
  if (!pptxModulePromise) pptxModulePromise = import("pptxviewjs");
  return pptxModulePromise;
}

export async function createPptxRenderer(
  content: ViewerContentBytes,
  onLoadTiming?: (timing: PptxSourceLoadTiming) => void,
): Promise<PptxRenderer> {
  const totalStartedAt = now();
  const readBytesStartedAt = now();
  const buffer = await readPptxBytes(content);
  const readBytesMs = now() - readBytesStartedAt;

  const importPptxStartedAt = now();
  const pptxPromise = loadPptx().then((pptx) => ({
    pptx,
    durationMs: now() - importPptxStartedAt,
  }));
  const pptx = await pptxPromise;
  const { PPTXViewer } = pptx.pptx;
  const offscreen = document.createElement("canvas");
  const viewer = new PPTXViewer({
    canvas: offscreen,
    slideSizeMode: "actual",
    autoExposeGlobals: false,
    autoChartRerenderDelayMs: 0,
    enableThumbnails: false,
  });
  const loadedViewer = viewer as unknown as LoadedPptxViewer;

  const loadFileStartedAt = now();
  try {
    await viewer.loadFile(buffer);
  } catch (error) {
    viewer.destroy?.();
    throw toPptxFormatError(error, {
      kind: "load_failed",
      message: "Failed to parse presentation.",
    });
  }
  const loadFileMs = now() - loadFileStartedAt;

  const readSlideSizeStartedAt = now();
  const baseSize = readLoadedSlideSize(loadedViewer);
  const readSlideSizeMs = now() - readSlideSizeStartedAt;

  let slideCount: number;
  const inspectStartedAt = now();
  try {
    slideCount = viewer.getSlideCount();
  } catch (error) {
    viewer.destroy?.();
    throw toPptxFormatError(error, {
      kind: "load_failed",
      message: "Failed to inspect presentation slides.",
    });
  }
  const inspectMs = now() - inspectStartedAt;
  if (!Number.isInteger(slideCount) || slideCount <= 0) {
    viewer.destroy?.();
    throw new PptxRendererError(
      "load_failed",
      "Presentation does not contain any slides.",
    );
  }

  onLoadTiming?.({
    byteLength: buffer.byteLength,
    importPptxMs: pptx.durationMs,
    inspectMs,
    loadFileMs,
    readBytesMs,
    readSlideSizeMs,
    slideCount,
    totalMs: now() - totalStartedAt,
  });

  let disposed = false;

  return {
    slideCount,
    baseSize,
    async renderSlide({ slideIndex, canvas, renderScale }) {
      if (disposed) {
        throw new PptxRendererError(
          "disposed",
          "Presentation renderer was disposed.",
        );
      }
      if (!isValidSlideIndex(slideIndex, slideCount)) {
        throw new PptxRendererError(
          "index_out_of_range",
          `Slide ${slideIndex + 1} is outside the presentation.`,
        );
      }
      if (!isValidRenderScale(renderScale)) {
        throw new PptxRendererError(
          "bounds",
          "Render scale must be a positive finite number.",
        );
      }
      try {
        setPptxRenderPixelRatio(loadedViewer, canvas, baseSize, renderScale);
        await viewer.renderSlide(slideIndex, canvas, {
          scale: renderScale,
          quality: "high",
        });
      } catch (error) {
        throw toPptxFormatError(error, {
          kind: "render_failed",
          message: `Failed to render slide ${slideIndex + 1}.`,
        });
      }
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      viewer.destroy?.();
    },
  };
}

function toPptxFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions,
): PptxRendererError {
  if (error instanceof PptxRendererError) return error;
  if (isViewerFormatError(error)) {
    return new PptxRendererError(error.kind, error.message, error.cause);
  }
  return new PptxRendererError(options.kind, options.message, error);
}

function readPptxBytes(content: ViewerContentBytes): Promise<ArrayBuffer> {
  return content.readBytes();
}

type LoadedPptxViewer = {
  getSlideDimensions?: () => unknown;
  processor?: unknown;
  presentation?: unknown;
};

type LoadedPptxProcessor = {
  getSlideDimensions?: () => unknown;
  processor?: unknown;
  presentation?: unknown;
  renderContext?: {
    pixelRatio?: number;
    dpi?: number;
  };
  setPixelRatio?: (ratio: number) => void;
};

function readLoadedSlideSize(viewer: LoadedPptxViewer): PptxSize {
  return (
    parseLoadedSlideSize(readLoadedSlideDimensions(viewer)) ??
    DEFAULT_PPTX_SLIDE_SIZE
  );
}

function readLoadedSlideDimensions(viewer: LoadedPptxViewer): unknown {
  try {
    const dimensions = viewer.getSlideDimensions?.();
    if (dimensions) return dimensions;
  } catch {
    /* fall through to exposed presentation objects */
  }

  const processor = viewer.processor as LoadedPptxProcessor | undefined;
  try {
    const dimensions = processor?.getSlideDimensions?.();
    if (dimensions) return dimensions;
  } catch {
    /* fall through to presentation fields */
  }

  return (
    readPresentationSlideSize(viewer.presentation) ??
    readPresentationSlideSize(processor?.presentation) ??
    readPresentationSlideSize(
      (processor?.processor as LoadedPptxProcessor | undefined)?.presentation,
    )
  );
}

function readPresentationSlideSize(presentation: unknown): unknown {
  if (!presentation || typeof presentation !== "object") return null;
  const slideSize = (presentation as { slideSize?: unknown }).slideSize;
  return slideSize ?? null;
}

function parseLoadedSlideSize(value: unknown): PptxSize | null {
  if (!value || typeof value !== "object") return null;
  const { cx, cy } = value as { cx?: unknown; cy?: unknown };
  const widthEmu = Number(cx);
  const heightEmu = Number(cy);
  if (
    !Number.isFinite(widthEmu) ||
    !Number.isFinite(heightEmu) ||
    widthEmu <= 0 ||
    heightEmu <= 0
  ) {
    return null;
  }

  const width = Math.round(widthEmu / 9525);
  const height = Math.round(heightEmu / 9525);
  if (width <= 0 || height <= 0) return null;
  return { width, height };
}

function setPptxRenderPixelRatio(
  viewer: LoadedPptxViewer,
  canvas: HTMLCanvasElement,
  baseSize: PptxSize,
  renderScale: number,
) {
  const logicalWidth = Number.parseFloat(canvas.style.width);
  const zoomScale =
    Number.isFinite(logicalWidth) && logicalWidth > 0 && baseSize.width > 0
      ? logicalWidth / baseSize.width
      : 1;
  const pixelRatio = renderScale / zoomScale;
  if (!Number.isFinite(pixelRatio) || pixelRatio <= 0) return;

  const processor = viewer.processor as LoadedPptxProcessor | undefined;
  const innerProcessor = processor?.processor as
    | LoadedPptxProcessor
    | undefined;
  setProcessorPixelRatio(processor, pixelRatio);
  setProcessorPixelRatio(innerProcessor, pixelRatio);
}

function setProcessorPixelRatio(
  processor: LoadedPptxProcessor | undefined,
  pixelRatio: number,
) {
  if (!processor) return;
  if (typeof processor.setPixelRatio === "function") {
    try {
      processor.setPixelRatio(pixelRatio);
      return;
    } catch {
      /* fall through to direct renderContext patching */
    }
  }
  if (!processor.renderContext) return;
  processor.renderContext.pixelRatio = pixelRatio;
  processor.renderContext.dpi = pixelRatio * 96;
}

function isValidSlideIndex(slideIndex: number, slideCount: number) {
  return (
    Number.isInteger(slideIndex) && slideIndex >= 0 && slideIndex < slideCount
  );
}

function isValidRenderScale(renderScale: number) {
  return Number.isFinite(renderScale) && renderScale > 0;
}

function now() {
  return typeof performance === "undefined" ? Date.now() : performance.now();
}

export function resetPptxRendererModules() {
  pptxModulePromise = null;
}

export function preloadPptxRenderer() {
  void loadPptx();
}

export const PPTX_SCROLL_IDLE_MS = 120;

export interface PptxScrollActivity {
  handleScroll(): void;
  isScrolling(): boolean;
  onIdle(callback: () => void): () => void;
}

export function createPptxScrollActivity(
  idleMs = PPTX_SCROLL_IDLE_MS,
): PptxScrollActivity {
  let isScrolling = false;
  let timer = 0;
  const waiters = new Set<() => void>();

  return {
    handleScroll() {
      isScrolling = true;
      clearTimeout(timer);
      timer = window.setTimeout(() => {
        isScrolling = false;
        const pending = [...waiters];
        waiters.clear();
        for (const callback of pending) callback();
      }, idleMs);
    },
    isScrolling: () => isScrolling,
    onIdle(callback: () => void) {
      waiters.add(callback);
      return () => waiters.delete(callback);
    },
  };
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

export function usePptxViewportWidth({
  enabled = true,
}: {
  enabled?: boolean;
} = {}) {
  const [containerElement, setContainerElement] =
    React.useState<HTMLDivElement | null>(null);
  const [viewportWidth, setViewportWidth] = React.useState<number | null>(null);

  useKeyedLayoutEffect(enabled ? null : "reset", () => {
    setViewportWidth((current) => (current == null ? current : null));
  });

  useKeyedLayoutEffect(
    enabled && containerElement ? joinEffectKey([containerElement]) : null,
    () => {
      if (!containerElement) return;

      let frame = 0;
      let latest = resolvePptxMeasuredWidth(containerElement.clientWidth);
      setViewportWidth(latest);
      if (typeof ResizeObserver === "undefined") return;

      let observer: ResizeObserver | null = null;
      try {
        observer = new ResizeObserver((entries) => {
          for (const entry of entries) {
            latest = resolvePptxMeasuredWidth(
              (entry.target as HTMLElement).clientWidth,
            );
          }
          if (frame) return;
          frame = -1;
          const requestedFrame = requestAnimationFrame(() => {
            frame = 0;
            setViewportWidth((current) =>
              current === latest ? current : latest,
            );
          });
          if (frame === -1) frame = requestedFrame;
        });
        observer.observe(containerElement);
      } catch {
        if (frame > 0) cancelAnimationFrame(frame);
        observer?.disconnect();
        /* Keep the initial measurement when ResizeObserver is unavailable at runtime. */
        return;
      }

      return () => {
        if (frame > 0) cancelAnimationFrame(frame);
        observer?.disconnect();
      };
    },
  );

  return { containerRef: setContainerElement, viewportWidth };
}

function resolvePptxMeasuredWidth(value: number) {
  return Number.isFinite(value) && value > 0 ? value : null;
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";

import {
  clamp,
  getScaledSlideSize,
  getVisibleSlideSize,
  type PptxSize,
} from "./pptx-viewer-core";
import {
  PPTX_ZOOM_INTENT_MAX_AGE_MS,
  type PptxZoomTransaction,
} from "./pptx-viewer-zoom-motion";
import type { ViewerDocumentZoomMotionController } from "./viewer-types";

export const PPTX_READING_MARKER_RATIO = 0.2;
export const PPTX_RENDER_FIT_PERFECTLY_OVERSCAN_PX = 32;
export const PPTX_RENDER_WINDOW_OVERSCAN_PX = 1000;
export const PPTX_SCROLL_REBASE_CONTAINER_PX = 12_000_000;
export const PPTX_SCROLL_REBASE_TRIGGER_PX = 1_000_000;
export const PPTX_SCROLL_REBASE_TARGET_PX = 2_000_000;
export const PPTX_SCROLL_REBASE_TARGET_BOTTOM_PX =
  PPTX_SCROLL_REBASE_CONTAINER_PX - PPTX_SCROLL_REBASE_TARGET_PX;
export const PPTX_SCROLL_REBASE_THRESHOLD_PX =
  PPTX_SCROLL_REBASE_CONTAINER_PX - PPTX_SCROLL_REBASE_TRIGGER_PX;
export const PPTX_SCROLL_POSITION_EPSILON = 1;

export interface PptxSlideLayout {
  slideCount: number;
  slideTopPadding: number;
  slideGap: number;
  slideHeight: number;
  slideWidth: number;
  slideStride: number;
  totalHeight: number;
}

export interface PptxVirtualSlide {
  height: number;
  index: number;
  key: string;
  slideNumber: number;
  top: number;
  width: number;
}

export interface PptxRenderedSlideWindow {
  afterHeight: number;
  beforeHeight: number;
  height: number;
  slides: Array<PptxVirtualSlide & { windowTop: number }>;
  stickyBottomInset: number;
  stickyTopInset: number;
}

export interface PptxRenderPixelWindow {
  bottom: number;
  top: number;
}

export interface PptxScrollMetrics {
  physicalScrollHeight: number;
  physicalScrollTop: number;
  scrollPageOffset: number;
  scrollTop: number;
  viewportHeight: number;
}

export interface PptxScrollRebasePosition {
  physicalScrollTop: number;
  scrollPageOffset: number;
}

export interface PptxSlideLayoutInput {
  baseSize: PptxSize;
  zoomScale: number;
  rotation: number;
  slideCount: number;
  slideGap: number;
  slidePadding: number;
}

export interface PptxVisibleSlideInput {
  layout: PptxSlideLayout;
  onVisibleSlideChange?: (slide: number) => void;
  onScrollProgressChange?: (progress: number) => void;
  zoomMotion?: ViewerDocumentZoomMotionController<PptxZoomTransaction>;
}

type PptxReadingAnchor =
  | {
      kind: "top";
    }
  | {
      kind: "slide";
      slideNumber: number;
      yPercent: number;
    };

export function createPptxSlideLayout({
  baseSize,
  zoomScale,
  rotation,
  slideCount,
  slideGap,
  slidePadding,
}: PptxSlideLayoutInput): PptxSlideLayout {
  const slideSize = getScaledSlideSize(baseSize, zoomScale);
  const visibleSize = getVisibleSlideSize(slideSize, rotation);
  const normalizedSlideCount = Number.isFinite(slideCount)
    ? Math.max(0, Math.floor(slideCount))
    : 0;
  // The gap scales with the slide, while the outer viewer inset stays fixed so
  // the first loaded slide occupies the exact p-4 skeleton frame. NOT rounded:
  // slide dimensions
  // (getScaledSlideSize) are fractional, so leaving the gap fractional too
  // keeps gap / slide height exactly constant and the layout perfectly linear.
  // (PDF rounds its gap only because its page dimensions are already
  // integer-rounded; rounding here would gain no integer offsets, just error.)
  const safeZoomScale =
    Number.isFinite(zoomScale) && zoomScale > 0 ? zoomScale : 1;
  const normalizedSlideGap =
    Number.isFinite(slideGap) && slideGap > 0 ? slideGap * safeZoomScale : 0;
  const normalizedSlidePadding =
    Number.isFinite(slidePadding) && slidePadding > 0 ? slidePadding : 0;
  const gapCount = Math.max(0, normalizedSlideCount - 1);

  return {
    slideCount: normalizedSlideCount,
    slideTopPadding: normalizedSlidePadding,
    slideGap: normalizedSlideGap,
    slideHeight: visibleSize.height,
    slideWidth: visibleSize.width,
    slideStride: visibleSize.height + normalizedSlideGap,
    totalHeight:
      normalizedSlidePadding * 2 +
      visibleSize.height * normalizedSlideCount +
      normalizedSlideGap * gapCount,
  };
}

export function getPptxSlideAtScrollMarker(
  layout: PptxSlideLayout,
  markerScrollTop: number,
) {
  if (layout.slideCount <= 1 || layout.slideStride <= 0) return 1;

  const slideIndex = Math.floor(
    (markerScrollTop - layout.slideTopPadding) / layout.slideStride,
  );
  return clamp(slideIndex + 1, 1, layout.slideCount);
}

export function getPptxSlideTop(layout: PptxSlideLayout, slideIndex: number) {
  return layout.slideTopPadding + slideIndex * layout.slideStride;
}

export function getPptxVirtualSlides({
  layout,
  overscanSlides = 2,
  scrollTop,
  viewportHeight,
}: {
  layout: PptxSlideLayout;
  overscanSlides?: number;
  scrollTop: number;
  viewportHeight: number;
}): PptxVirtualSlide[] {
  if (layout.slideCount === 0) return [];

  const safeViewportHeight =
    Number.isFinite(viewportHeight) && viewportHeight > 0
      ? viewportHeight
      : layout.slideHeight;
  const safeScrollTop =
    Number.isFinite(scrollTop) && scrollTop > 0 ? scrollTop : 0;
  const safeOverscanSlides =
    Number.isFinite(overscanSlides) && overscanSlides > 0
      ? Math.floor(overscanSlides)
      : 0;
  const firstVisibleIndex =
    layout.slideStride > 0
      ? Math.floor(
          (safeScrollTop - layout.slideTopPadding) / layout.slideStride,
        )
      : 0;
  const lastVisibleIndex =
    layout.slideStride > 0
      ? Math.floor(
          (safeScrollTop + safeViewportHeight - layout.slideTopPadding) /
            layout.slideStride,
        )
      : 0;
  const firstIndex = clamp(
    firstVisibleIndex - safeOverscanSlides,
    0,
    layout.slideCount - 1,
  );
  const lastIndex = clamp(
    lastVisibleIndex + safeOverscanSlides,
    0,
    layout.slideCount - 1,
  );

  return Array.from(
    { length: lastIndex - firstIndex + 1 },
    (_, offset): PptxVirtualSlide => {
      const index = firstIndex + offset;
      const slideNumber = index + 1;
      return {
        height: layout.slideHeight,
        index,
        key: String(slideNumber),
        slideNumber,
        top: getPptxSlideTop(layout, index),
        width: layout.slideWidth,
      };
    },
  );
}

export function getPptxRenderSlides({
  fitPerfectly = false,
  fitPerfectlyOverscanPx = PPTX_RENDER_FIT_PERFECTLY_OVERSCAN_PX,
  layout,
  overscanPx = PPTX_RENDER_WINDOW_OVERSCAN_PX,
  scrollTop,
  viewportHeight,
}: {
  fitPerfectly?: boolean;
  fitPerfectlyOverscanPx?: number;
  layout: PptxSlideLayout;
  overscanPx?: number;
  scrollTop: number;
  viewportHeight: number;
}): PptxVirtualSlide[] {
  if (layout.slideCount === 0) return [];

  const window = createPptxWindowFromScrollPosition({
    fitPerfectly,
    fitPerfectlyOverscanPx,
    overscanPx,
    scrollHeight: layout.totalHeight,
    scrollTop,
    viewportHeight,
  });

  return getPptxSlidesInRange({
    layout,
    startOffset: window.top,
    endOffset: window.bottom,
  });
}

export function getPptxRenderedSlideWindow({
  layout,
  physicalScrollHeight = layout.totalHeight,
  scrollPageOffset = 0,
  slides,
  viewportHeight,
}: {
  layout: PptxSlideLayout;
  physicalScrollHeight?: number;
  scrollPageOffset?: number;
  slides: readonly PptxVirtualSlide[];
  viewportHeight: number;
}): PptxRenderedSlideWindow | null {
  const renderedSlides = [...slides].sort((a, b) => a.index - b.index);
  if (renderedSlides.length === 0) return null;

  const logicalBeforeHeight = renderedSlides[0]?.top ?? 0;
  const windowBottom = Math.max(
    ...renderedSlides.map((slide) => slide.top + slide.height),
  );
  const height = Math.max(0, windowBottom - logicalBeforeHeight);
  const beforeHeight = getPptxPagedLayoutTop({
    logicalTop: logicalBeforeHeight,
    scrollPageOffset,
    totalHeight: layout.totalHeight,
    viewportHeight,
  });
  const safeViewportHeight =
    Number.isFinite(viewportHeight) && viewportHeight > 0
      ? viewportHeight
      : layout.slideHeight > 0
        ? layout.slideHeight
        : 0;
  const stickyCoverInset =
    safeViewportHeight > 0 ? -Math.max(0, height - safeViewportHeight) : 0;
  const afterHeight = Math.max(
    0,
    safeSize(physicalScrollHeight) - beforeHeight - height,
  );
  // The sticky cover clamp only ever needs to slide the window over CONTENT
  // the viewport can reach. When the window already holds the document's
  // first/last slide, the spacer beyond it is pure edge padding — relax that
  // side's inset by the spacer so the settled window keeps its flow position
  // at the scroll extremes. Without the relaxation the clamp drags the window
  // over the edge padding at scroll 0/max, and the settled layout stops being
  // a single linear function of scale (which the reading-fraction rebase
  // depends on to restore the reading line exactly across a re-fit).
  const includesFirstSlide = renderedSlides[0].index === 0;
  const includesLastSlide =
    renderedSlides[renderedSlides.length - 1].index === layout.slideCount - 1;

  return {
    afterHeight,
    beforeHeight,
    height,
    slides: renderedSlides.map((slide) => ({
      ...slide,
      windowTop: slide.top - logicalBeforeHeight,
    })),
    stickyBottomInset:
      stickyCoverInset - (includesFirstSlide ? beforeHeight : 0),
    stickyTopInset: stickyCoverInset - (includesLastSlide ? afterHeight : 0),
  };
}

export function createPptxWindowFromScrollPosition({
  fitPerfectly = false,
  fitPerfectlyOverscanPx = 0,
  overscanPx,
  scrollHeight,
  scrollTop,
  viewportHeight,
}: {
  fitPerfectly?: boolean;
  fitPerfectlyOverscanPx?: number;
  overscanPx: number;
  scrollHeight: number;
  scrollTop: number;
  viewportHeight: number;
}): PptxRenderPixelWindow {
  const safeOverscanPx = safePadding(overscanPx);
  const safeScrollHeight = safeSize(scrollHeight);
  const safeScrollTop = Math.max(0, finiteNumber(scrollTop));
  const safeViewportHeight = Math.max(0, finiteNumber(viewportHeight));
  const windowHeight = safeViewportHeight + safeOverscanPx * 2;
  const fitPerfectlyOverscan = safePadding(fitPerfectlyOverscanPx);
  const effectiveHeight = fitPerfectly
    ? safeViewportHeight + fitPerfectlyOverscan * 2
    : windowHeight;

  if (windowHeight >= safeScrollHeight || fitPerfectly) {
    const fitScrollTop = Math.min(safeScrollTop, safeScrollHeight);
    const top = Math.max(fitScrollTop - fitPerfectlyOverscan, 0);
    const bottom = Math.min(fitScrollTop + effectiveHeight, safeScrollHeight);
    return {
      bottom: Math.ceil(Math.max(bottom, top)),
      top: Math.floor(Math.max(0, top)),
    };
  }

  const scrollCenter = safeScrollTop + safeViewportHeight / 2;
  let top = scrollCenter - windowHeight / 2;
  let bottom = top + windowHeight;

  if (top < 0) {
    top = 0;
    bottom = windowHeight;
  }
  if (bottom > safeScrollHeight) {
    bottom = safeScrollHeight;
    top = safeScrollHeight - windowHeight;
  }

  return {
    bottom: Math.ceil(Math.max(bottom, top)),
    top: Math.floor(Math.max(0, top)),
  };
}

export function getPptxPhysicalScrollHeight({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  const safeTotalHeight = safeSize(totalHeight);
  return shouldRebasePptxScroll({
    totalHeight: safeTotalHeight,
    viewportHeight,
  })
    ? Math.min(safeTotalHeight, PPTX_SCROLL_REBASE_CONTAINER_PX)
    : safeTotalHeight;
}

export function getPptxLogicalScrollTop({
  physicalScrollTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  physicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  return clamp(
    finiteNumber(physicalScrollTop) + safePadding(scrollPageOffset),
    0,
    getPptxMaxLogicalScrollTop({ totalHeight, viewportHeight }),
  );
}

export function resolvePptxPhysicalScrollPosition({
  logicalScrollTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  logicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}): PptxScrollRebasePosition {
  const safeLogicalScrollTop = clamp(
    finiteNumber(logicalScrollTop),
    0,
    getPptxMaxLogicalScrollTop({ totalHeight, viewportHeight }),
  );

  if (!shouldRebasePptxScroll({ totalHeight, viewportHeight })) {
    return {
      physicalScrollTop: clamp(
        safeLogicalScrollTop,
        0,
        getPptxMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
      ),
      scrollPageOffset: 0,
    };
  }

  const currentPageOffset = clampPptxScrollPageOffset({
    scrollPageOffset,
    totalHeight,
    viewportHeight,
  });
  const physicalScrollTop = safeLogicalScrollTop - currentPageOffset;
  const maxPhysicalScrollTop = getPptxMaxPhysicalScrollTop({
    totalHeight,
    viewportHeight,
  });
  const maxPageOffset = getPptxMaxScrollPageOffset({
    totalHeight,
    viewportHeight,
  });
  const shouldMoveDown =
    physicalScrollTop > PPTX_SCROLL_REBASE_THRESHOLD_PX &&
    currentPageOffset < maxPageOffset;
  const shouldMoveUp =
    physicalScrollTop < PPTX_SCROLL_REBASE_TRIGGER_PX && currentPageOffset > 0;

  if (
    physicalScrollTop < 0 ||
    physicalScrollTop > maxPhysicalScrollTop ||
    shouldMoveDown ||
    shouldMoveUp
  ) {
    return resolvePptxScrollPageWindow({
      logicalScrollTop: safeLogicalScrollTop,
      preferredPhysicalScrollTop: shouldMoveUp
        ? Math.min(PPTX_SCROLL_REBASE_TARGET_BOTTOM_PX, maxPhysicalScrollTop)
        : PPTX_SCROLL_REBASE_TARGET_PX,
      totalHeight,
      viewportHeight,
    });
  }

  return {
    physicalScrollTop: roundPptxScrollPixel(
      clamp(physicalScrollTop, 0, maxPhysicalScrollTop),
    ),
    scrollPageOffset: currentPageOffset,
  };
}

export function getPptxPagedLayoutTop({
  logicalTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  logicalTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  if (!shouldRebasePptxScroll({ totalHeight, viewportHeight })) {
    return finiteNumber(logicalTop);
  }
  return Math.max(0, finiteNumber(logicalTop) - safePadding(scrollPageOffset));
}

export function readPptxScrollMetrics({
  scrollPageOffset,
  totalHeight,
  viewportElement,
}: {
  scrollPageOffset: number;
  totalHeight: number;
  viewportElement: HTMLDivElement | null;
}): PptxScrollMetrics {
  const viewportHeight = viewportElement?.clientHeight ?? 0;
  const physicalScrollTop = viewportElement?.scrollTop ?? 0;
  const physicalScrollHeight = getPptxPhysicalScrollHeight({
    totalHeight,
    viewportHeight,
  });
  const isRebased = physicalScrollHeight < totalHeight;

  return {
    physicalScrollHeight,
    physicalScrollTop,
    scrollPageOffset: isRebased ? scrollPageOffset : 0,
    scrollTop: isRebased
      ? getPptxLogicalScrollTop({
          physicalScrollTop,
          scrollPageOffset,
          totalHeight,
          viewportHeight,
        })
      : Math.max(0, physicalScrollTop),
    viewportHeight,
  };
}

export function usePptxVisibleSlide({
  layout,
  onVisibleSlideChange,
  onScrollProgressChange,
  zoomMotion,
}: PptxVisibleSlideInput) {
  const [currentSlide, setCurrentSlide] = React.useState(1);
  const scrollViewportRef = React.useRef<HTMLDivElement | null>(null);
  const lastReportedSlide = React.useRef(0);
  const lastVisibleSlideCallback = React.useRef(onVisibleSlideChange);
  const committedLayoutRef = React.useRef(layout);
  const scrollPageOffsetRef = React.useRef(0);
  const pendingZoomIntentRef = React.useRef<{
    capturedAt: number;
    transaction: PptxZoomTransaction;
  } | null>(null);
  const activeZoomMotionCancelRef = React.useRef<(() => void) | null>(null);
  const layoutEffectKey = getPptxSlideLayoutKey(layout);

  // Interrupting a zoom relax snaps to its committed endpoint: the layout and
  // scroll landed in the zoom's own commit, so clearing the transform is
  // always safe and never moves the settled geometry.
  const cancelZoomMotion = React.useCallback(() => {
    pendingZoomIntentRef.current = null;
    const cancelActiveZoomMotion = activeZoomMotionCancelRef.current;
    activeZoomMotionCancelRef.current = null;
    cancelActiveZoomMotion?.();
  }, []);

  if (lastVisibleSlideCallback.current !== onVisibleSlideChange) {
    lastVisibleSlideCallback.current = onVisibleSlideChange;
    lastReportedSlide.current = 0;
  }

  const getScrollMetrics = React.useCallback(
    () =>
      readPptxScrollMetrics({
        scrollPageOffset: scrollPageOffsetRef.current,
        totalHeight: layout.totalHeight,
        viewportElement: scrollViewportRef.current,
      }),
    [layout.totalHeight],
  );

  // Called in the zoom gesture's own task, against the pre-zoom layout and
  // painted DOM; the layout commit the gesture causes consumes the intent.
  const captureZoomIntent = React.useCallback(() => {
    const viewport = scrollViewportRef.current;
    if (!viewport || !zoomMotion) {
      pendingZoomIntentRef.current = null;
      return;
    }
    const metrics = readPptxScrollMetrics({
      scrollPageOffset: scrollPageOffsetRef.current,
      totalHeight: layout.totalHeight,
      viewportElement: viewport,
    });
    const transaction = zoomMotion.capture({
      scrollTop: metrics.scrollTop,
      viewportElement: viewport,
    });
    pendingZoomIntentRef.current =
      transaction == null
        ? null
        : { capturedAt: readPptxZoomNow(), transaction };
  }, [layout.totalHeight, zoomMotion]);

  const syncPhysicalScrollPosition = React.useCallback(
    (viewport: HTMLDivElement) => {
      const metrics = readPptxScrollMetrics({
        scrollPageOffset: scrollPageOffsetRef.current,
        totalHeight: layout.totalHeight,
        viewportElement: viewport,
      });
      if (metrics.physicalScrollHeight >= layout.totalHeight) {
        scrollPageOffsetRef.current = 0;
        return {
          ...metrics,
          scrollPageOffset: 0,
        };
      }

      const position = resolvePptxPhysicalScrollPosition({
        logicalScrollTop: metrics.scrollTop,
        scrollPageOffset: metrics.scrollPageOffset,
        totalHeight: layout.totalHeight,
        viewportHeight: metrics.viewportHeight,
      });
      scrollPageOffsetRef.current = position.scrollPageOffset;
      setViewportPhysicalScrollTop(viewport, position.physicalScrollTop);

      return {
        ...metrics,
        physicalScrollTop: position.physicalScrollTop,
        scrollPageOffset: position.scrollPageOffset,
      };
    },
    [layout.totalHeight],
  );

  const scrollViewportToLogicalTop = React.useCallback(
    (viewport: HTMLDivElement, targetTop: number) => {
      const position = resolvePptxPhysicalScrollPosition({
        logicalScrollTop: targetTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        totalHeight: layout.totalHeight,
        viewportHeight: viewport.clientHeight,
      });
      scrollPageOffsetRef.current = position.scrollPageOffset;
      setViewportPhysicalScrollTop(viewport, position.physicalScrollTop);
    },
    [layout.totalHeight],
  );

  useKeyedLayoutEffect(layoutEffectKey, () => {
    const previousLayout = committedLayoutRef.current;
    committedLayoutRef.current = layout;

    if (arePptxSlideLayoutsEqual(previousLayout, layout)) return;

    const viewport = scrollViewportRef.current;
    if (!viewport) return;

    // A fresh layout commit owns the visual layer; an in-flight zoom relax
    // against the previous layout can no longer settle correctly.
    const pendingZoomIntent = pendingZoomIntentRef.current;
    pendingZoomIntentRef.current = null;
    cancelZoomMotion();

    if (
      pendingZoomIntent &&
      zoomMotion &&
      readPptxZoomNow() - pendingZoomIntent.capturedAt <=
        PPTX_ZOOM_INTENT_MAX_AGE_MS
    ) {
      const zoomTarget = zoomMotion.resolveScrollTarget({
        transaction: pendingZoomIntent.transaction,
        viewportElement: viewport,
      });
      if (zoomTarget) {
        // Commit-then-relax: land the centered scroll inside this commit
        // (through the paged-scroll mapping), then relax the painted FLIP
        // over it. Raw scrollLeft assignment on purpose — the browser clamps
        // to the live scrollable range, including RTL's negative space.
        scrollViewportToLogicalTop(viewport, zoomTarget.top);
        if (zoomTarget.left != null && Number.isFinite(zoomTarget.left)) {
          viewport.scrollLeft = zoomTarget.left;
        }
        activeZoomMotionCancelRef.current = zoomMotion.play({
          transaction: pendingZoomIntent.transaction,
          viewportElement: viewport,
        });
        return;
      }
    }

    const previousLogicalScrollTop = getPptxLogicalScrollTop({
      physicalScrollTop: viewport.scrollTop,
      scrollPageOffset: scrollPageOffsetRef.current,
      totalHeight: previousLayout.totalHeight,
      viewportHeight: viewport.clientHeight,
    });
    const anchor = capturePptxReadingAnchor(
      previousLayout,
      viewport,
      previousLogicalScrollTop,
    );
    if (!anchor) return;

    const targetTop = getPptxReadingAnchorScrollTop(layout, viewport, anchor);
    if (targetTop != null) scrollViewportToLogicalTop(viewport, targetTop);
  });

  const handleScroll = React.useCallback(() => {
    const viewport = scrollViewportRef.current;
    if (!viewport) return;

    const metrics = syncPhysicalScrollPosition(viewport);
    const isRebased = metrics.physicalScrollHeight < layout.totalHeight;
    const scrollable = isRebased
      ? layout.totalHeight - metrics.viewportHeight
      : viewport.scrollHeight - metrics.viewportHeight;
    onScrollProgressChange?.(
      scrollable > 0
        ? clamp(
            (isRebased ? metrics.scrollTop : viewport.scrollTop) / scrollable,
            0,
            1,
          )
        : 0,
    );

    const markerScrollTop =
      metrics.scrollTop + metrics.viewportHeight * PPTX_READING_MARKER_RATIO;
    const visibleSlide = getPptxSlideAtScrollMarker(layout, markerScrollTop);

    if (visibleSlide && visibleSlide !== lastReportedSlide.current) {
      lastReportedSlide.current = visibleSlide;
      setCurrentSlide(visibleSlide);
      onVisibleSlideChange?.(visibleSlide);
    }
  }, [
    layout,
    onScrollProgressChange,
    onVisibleSlideChange,
    syncPhysicalScrollPosition,
  ]);

  return {
    captureZoomIntent,
    currentSlide,
    getScrollMetrics,
    handleScroll,
    scrollViewportRef,
  };
}

function readPptxZoomNow() {
  return typeof performance !== "undefined" &&
    typeof performance.now === "function"
    ? performance.now()
    : Date.now();
}

function getPptxSlideLayoutKey(layout: PptxSlideLayout) {
  return [
    layout.slideCount,
    layout.slideTopPadding,
    layout.slideGap,
    layout.slideHeight,
    layout.slideWidth,
    layout.slideStride,
    layout.totalHeight,
  ].join("\u0000");
}

function capturePptxReadingAnchor(
  layout: PptxSlideLayout,
  viewport: HTMLDivElement,
  scrollTop: number,
): PptxReadingAnchor | null {
  if (layout.slideCount === 0) return null;
  if (scrollTop <= 0) return { kind: "top" };

  const markerScrollTop =
    scrollTop + viewport.clientHeight * PPTX_READING_MARKER_RATIO;
  const slideNumber = getPptxSlideAtScrollMarker(layout, markerScrollTop);
  const slideTop = getPptxSlideTop(layout, slideNumber - 1);
  if (layout.slideHeight <= 0) return null;

  return {
    kind: "slide",
    slideNumber,
    yPercent: clamp((markerScrollTop - slideTop) / layout.slideHeight, 0, 1),
  };
}

function getPptxReadingAnchorScrollTop(
  layout: PptxSlideLayout,
  viewport: HTMLDivElement,
  anchor: PptxReadingAnchor,
) {
  if (anchor.kind === "top") {
    return 0;
  }

  if (anchor.slideNumber < 1 || anchor.slideNumber > layout.slideCount) {
    return null;
  }

  const slideTop = getPptxSlideTop(layout, anchor.slideNumber - 1);
  const targetTop =
    slideTop +
    layout.slideHeight * anchor.yPercent -
    viewport.clientHeight * PPTX_READING_MARKER_RATIO;
  const maxScrollTop = Math.max(0, layout.totalHeight - viewport.clientHeight);
  return clamp(targetTop, 0, maxScrollTop);
}

function arePptxSlideLayoutsEqual(
  previousLayout: PptxSlideLayout,
  nextLayout: PptxSlideLayout,
) {
  return (
    previousLayout.slideCount === nextLayout.slideCount &&
    previousLayout.slideTopPadding === nextLayout.slideTopPadding &&
    previousLayout.slideGap === nextLayout.slideGap &&
    previousLayout.slideHeight === nextLayout.slideHeight &&
    previousLayout.slideWidth === nextLayout.slideWidth &&
    previousLayout.slideStride === nextLayout.slideStride &&
    previousLayout.totalHeight === nextLayout.totalHeight
  );
}

function getPptxSlidesInRange({
  layout,
  startOffset,
  endOffset,
}: {
  layout: PptxSlideLayout;
  startOffset: number;
  endOffset: number;
}) {
  const safeStartOffset = Math.max(0, finiteNumber(startOffset));
  const safeEndOffset = Math.max(safeStartOffset, finiteNumber(endOffset));
  const firstIndex = getPptxSlideIndexAtOffset(layout, safeStartOffset);
  const lastIndex = getPptxSlideIndexAtOffset(layout, safeEndOffset);

  return createPptxSlideRange(layout, firstIndex, lastIndex);
}

function createPptxSlideRange(
  layout: PptxSlideLayout,
  firstIndex: number,
  lastIndex: number,
) {
  if (layout.slideCount === 0 || lastIndex < firstIndex) return [];

  return Array.from(
    { length: lastIndex - firstIndex + 1 },
    (_, offset): PptxVirtualSlide => {
      const index = firstIndex + offset;
      const slideNumber = index + 1;
      return {
        height: layout.slideHeight,
        index,
        key: String(slideNumber),
        slideNumber,
        top: getPptxSlideTop(layout, index),
        width: layout.slideWidth,
      };
    },
  );
}

function getPptxSlideIndexAtOffset(layout: PptxSlideLayout, offset: number) {
  if (layout.slideCount === 0 || layout.slideStride <= 0) return 0;

  return clamp(
    Math.floor(
      (finiteNumber(offset) - layout.slideTopPadding) / layout.slideStride,
    ),
    0,
    layout.slideCount - 1,
  );
}

function shouldRebasePptxScroll({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return (
    getPptxMaxLogicalScrollTop({ totalHeight, viewportHeight }) >
    PPTX_SCROLL_REBASE_THRESHOLD_PX
  );
}

function getPptxMaxLogicalScrollTop({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    safeSize(totalHeight) - Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getPptxMaxPhysicalScrollTop({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    getPptxPhysicalScrollHeight({ totalHeight, viewportHeight }) -
      Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getPptxMaxScrollPageOffset({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    getPptxMaxLogicalScrollTop({ totalHeight, viewportHeight }) -
      getPptxMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    0,
  );
}

function clampPptxScrollPageOffset({
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  return clamp(
    safePadding(scrollPageOffset),
    0,
    getPptxMaxScrollPageOffset({ totalHeight, viewportHeight }),
  );
}

function resolvePptxScrollPageWindow({
  logicalScrollTop,
  preferredPhysicalScrollTop,
  totalHeight,
  viewportHeight,
}: {
  logicalScrollTop: number;
  preferredPhysicalScrollTop: number;
  totalHeight: number;
  viewportHeight: number;
}): PptxScrollRebasePosition {
  let physicalScrollTop = roundPptxScrollPixel(
    clamp(
      finiteNumber(preferredPhysicalScrollTop),
      0,
      getPptxMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    ),
  );
  let scrollPageOffset = clampPptxScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalHeight,
    viewportHeight,
  });

  physicalScrollTop = roundPptxScrollPixel(
    clamp(
      logicalScrollTop - scrollPageOffset,
      0,
      getPptxMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    ),
  );
  scrollPageOffset = clampPptxScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalHeight,
    viewportHeight,
  });

  return { physicalScrollTop, scrollPageOffset };
}

function setViewportPhysicalScrollTop(
  viewport: HTMLDivElement,
  targetTop: number,
) {
  if (
    Math.abs(viewport.scrollTop - targetTop) <= PPTX_SCROLL_POSITION_EPSILON
  ) {
    return;
  }
  viewport.scrollTop = targetTop;
}

function roundPptxScrollPixel(value: number) {
  return Math.round(value);
}

function safeSize(value: number) {
  return Math.max(0, finiteNumber(value));
}

function safePadding(value: number) {
  return Math.max(0, finiteNumber(value));
}

function finiteNumber(value: number) {
  return Number.isFinite(value) ? value : 0;
}

import { clamp } from "./pptx-viewer-core";
import type { ViewerDocumentZoomMotionController } from "./viewer-types";

// Structural copy of PptxSlideLayout's zoom-relevant slice, so the visible-
// slide module (which consumes this one) is not also an import of it.
export type PptxZoomSlideLayout = {
  slideCount: number;
  slideTopPadding: number;
  slideHeight: number;
  slideStride: number;
  totalHeight: number;
};

// A toolbar zoom step re-anchors the viewport CENTER on both axes (Apple
// Preview semantics): the content point under the viewport center before the
// step is back under the viewport center after it, and a short FLIP relax
// scales the painted surface about that fixed point. The reading-marker
// restore (20% from the top, block axis only) stays the semantics for every
// other geometry change — re-fits, rotation, container resizes — where the
// intent is "keep my reading position", not "zoom the camera".
const PPTX_ZOOM_CENTER_MARKER_RATIO = 0.5;
const PPTX_ZOOM_MOTION_DURATION_MS = 200;
// easeOutCubic: fast attack, gentle landing — a linear relax reads as a
// hard stop at settle.
const PPTX_ZOOM_MOTION_EASING = "cubic-bezier(0.33, 1, 0.68, 1)";
const PPTX_ZOOM_MOTION_CLEANUP_MS = PPTX_ZOOM_MOTION_DURATION_MS + 50;
const PPTX_ZOOM_MOTION_MIN_TRANSLATE_PX = 0.5;
const PPTX_ZOOM_MOTION_MIN_SCALE_DELTA = 0.001;
// A rebased (paged) physical scroll detaches the stage box from the content
// scale, so the whole-surface FLIP would warp. Its signature is precise: the
// rebased axis is PINNED (the container keeps its size while the content
// rescales), so one axis barely moves while the other moves a lot. Testing for
// that beats a plain ratio tolerance — an honest slide stack carries small
// constant terms (rounded gaps, fixed outer padding) that put the block axis a
// couple of percent off the inline one. On a big jump a tight ratio tolerance
// then refuses the relax and the whole scale change lands in one frame —
// measured on the image viewer as an un-animated 620px snap on a multi-frame
// TIFF's fit-width, and this stack has the same shape of layout. The
// wide ratio net below still catches anything wilder, and the FLIP writes
// per-axis scales, so a slightly non-affine layout renders exactly.
const PPTX_ZOOM_MOTION_AXIS_FROZEN_DELTA = 0.02;
const PPTX_ZOOM_MOTION_AXIS_MOVED_DELTA = 0.05;
const PPTX_ZOOM_MOTION_AXIS_MISMATCH_RATIO = 0.25;

// The exact wait-out of the relax before the visual clip re-tightens; clip
// release is React-rendered state, so it outlives the inline transition.
export const PPTX_ZOOM_MOTION_TOTAL_MS = PPTX_ZOOM_MOTION_CLEANUP_MS + 50;

// A zoom intent is consumed by the layout commit its gesture causes; if no
// commit claims it in this window (scale already clamped, controlled scale
// ignored by the owner), it is stale and must not re-anchor a later,
// unrelated layout change.
export const PPTX_ZOOM_INTENT_MAX_AGE_MS = 400;

// The document surface shrink-wraps the slide column (width = slideWidth,
// exactly linear in scale) — the inline-anchor ruler. The FLIP relaxes on the
// virtual canvas inside it: the canvas spans the full (physical) scroll
// height and is NOT the kernel-registered surface, whose style the shell
// motion owns.
const PPTX_ZOOM_STAGE_SELECTOR = '[data-slot="pptx-viewer-document-surface"]';
const PPTX_ZOOM_VISUAL_LAYER_SELECTOR =
  '[data-slot="pptx-slide-virtual-canvas"]';

export type PptxZoomTransaction = {
  slideNumber: number;
  /**
   * Deliberately unclamped, like the reading anchor: the slide layout is
   * exactly linear in scale (fractional gap, fixed outer padding), so a
   * center marker resting in a gap restores by the same slide-relative
   * fraction.
   */
  yPercent: number;
  /** Viewport-center position as a fraction of the stage's inline size. */
  inlineFraction: number | null;
  /**
   * Same, on the BLOCK axis. Rect-derived like the inline one, so the solve
   * cannot be thrown off by anything the layout model does not know about —
   * chiefly the auto margins that centre a zoomed-out deck inside the pane.
   * The slide model stays the fallback for a rebased (paged) scroll, where
   * the stage stops spanning the deck.
   */
  blockFraction: number | null;
  /** Painted visual-layer rect at click time — the FLIP's "first" frame. */
  previousVisualRect: DOMRectReadOnly | null;
};

export function createPptxZoomMotionController(
  layout: PptxZoomSlideLayout,
): ViewerDocumentZoomMotionController<PptxZoomTransaction> {
  return {
    capture: ({ scrollTop, viewportElement }) =>
      capturePptxZoomTransaction({ layout, scrollTop, viewportElement }),
    resolveScrollTarget: ({ transaction, viewportElement }) =>
      resolvePptxZoomScrollTarget({ layout, transaction, viewportElement }),
    play: ({ transaction, viewportElement }) =>
      playPptxZoomMotion({ transaction, viewportElement }),
  };
}

export function capturePptxZoomTransaction({
  layout,
  scrollTop,
  viewportElement,
}: {
  layout: PptxZoomSlideLayout;
  /** LOGICAL scroll top — the caller maps out of the paged physical space. */
  scrollTop: number;
  viewportElement: HTMLDivElement;
}): PptxZoomTransaction | null {
  if (layout.slideCount === 0 || layout.slideHeight <= 0) return null;

  const viewportBlockSize = Math.max(0, viewportElement.clientHeight);
  const centerOffset =
    Math.max(0, scrollTop) + viewportBlockSize * PPTX_ZOOM_CENTER_MARKER_RATIO;
  const slideNumber = getPptxZoomSlideAtOffset(layout, centerOffset);
  const slideTop = getPptxZoomSlideTop(layout, slideNumber - 1);

  return {
    slideNumber,
    yPercent: (centerOffset - slideTop) / layout.slideHeight,
    inlineFraction: capturePptxZoomInlineFraction(viewportElement),
    blockFraction: capturePptxZoomBlockFraction(viewportElement),
    previousVisualRect: readElementRect(
      findPptxZoomVisualLayer(viewportElement),
    ),
  };
}

export function resolvePptxZoomScrollTarget({
  layout,
  transaction,
  viewportElement,
}: {
  layout: PptxZoomSlideLayout;
  transaction: PptxZoomTransaction;
  viewportElement: HTMLDivElement;
}): { left?: number; top: number } | null {
  if (
    layout.slideHeight <= 0 ||
    transaction.slideNumber < 1 ||
    transaction.slideNumber > layout.slideCount
  ) {
    return null;
  }

  const viewportBlockSize = Math.max(0, viewportElement.clientHeight);
  const maxScrollTop = Math.max(0, layout.totalHeight - viewportBlockSize);
  const slideTop = getPptxZoomSlideTop(layout, transaction.slideNumber - 1);
  // LOGICAL target — the caller maps back into the paged physical space.
  const top = clamp(
    resolvePptxZoomScrollTop({ layout, transaction, viewportElement }) ??
      slideTop +
        layout.slideHeight * transaction.yPercent -
        viewportBlockSize * PPTX_ZOOM_CENTER_MARKER_RATIO,
    0,
    maxScrollTop,
  );

  const left = resolvePptxZoomScrollLeft(viewportElement, transaction);
  return { top, ...(left == null ? null : { left }) };
}

// The stage is measured by live rects rather than re-deriving its centered
// offset, so the math is direction-agnostic: RTL scrollLeft coordinate spaces
// and the browser's own clamping both fall out for free.
function capturePptxZoomInlineFraction(viewportElement: HTMLDivElement) {
  const stageRect = readElementRect(findPptxZoomStage(viewportElement));
  if (!stageRect || stageRect.width <= 0) return null;
  return (
    (getViewportCenterX(viewportElement) - stageRect.left) / stageRect.width
  );
}

function capturePptxZoomBlockFraction(viewportElement: HTMLDivElement) {
  const stageRect = readElementRect(findPptxZoomStage(viewportElement));
  if (!stageRect || stageRect.height <= 0) return null;
  return (
    (getViewportCenterY(viewportElement) - stageRect.top) / stageRect.height
  );
}

// Scroll down by however far the anchored content point currently sits below
// the viewport centre — the block mirror of the inline solve. Only valid while
// the stage box IS the deck; a rebased scroll detaches the two and the caller
// falls back to the slide model.
function resolvePptxZoomScrollTop({
  layout,
  transaction,
  viewportElement,
}: {
  layout: PptxZoomSlideLayout;
  transaction: PptxZoomTransaction;
  viewportElement: HTMLDivElement;
}) {
  if (transaction.blockFraction == null) return null;
  const stageRect = readElementRect(findPptxZoomStage(viewportElement));
  if (!stageRect || stageRect.height <= 0) return null;
  if (Math.abs(stageRect.height - layout.totalHeight) > 2) return null;
  return (
    viewportElement.scrollTop +
    (stageRect.top + stageRect.height * transaction.blockFraction) -
    getViewportCenterY(viewportElement)
  );
}

function resolvePptxZoomScrollLeft(
  viewportElement: HTMLDivElement,
  transaction: PptxZoomTransaction,
) {
  if (transaction.inlineFraction == null) return undefined;
  const stageRect = readElementRect(findPptxZoomStage(viewportElement));
  if (!stageRect || stageRect.width <= 0) return undefined;

  // Scroll right by however far the anchored content point currently sits
  // right of the viewport center; the browser clamps to the scrollable range
  // (which also zeroes it out when the stage fits without overflow).
  return (
    viewportElement.scrollLeft +
    (stageRect.left + stageRect.width * transaction.inlineFraction) -
    getViewportCenterX(viewportElement)
  );
}

export function playPptxZoomMotion({
  transaction,
  viewportElement,
}: {
  transaction: PptxZoomTransaction;
  viewportElement: HTMLDivElement;
}): (() => void) | null {
  if (typeof requestAnimationFrame !== "function") return null;
  if (prefersReducedMotion()) return null;

  const previousRect = transaction.previousVisualRect;
  const visualLayer = findPptxZoomVisualLayer(viewportElement);
  if (!previousRect || !visualLayer) return null;

  const currentRect = readElementRect(visualLayer);
  if (
    !currentRect ||
    previousRect.width <= 0 ||
    previousRect.height <= 0 ||
    currentRect.width <= 0 ||
    currentRect.height <= 0
  ) {
    return null;
  }

  const scaleX = previousRect.width / currentRect.width;
  const scaleY = previousRect.height / currentRect.height;
  if (hasDetachedPptxZoomAxes(scaleX, scaleY)) {
    return null;
  }

  const translateX = previousRect.left - currentRect.left;
  const translateY = previousRect.top - currentRect.top;
  const hasVisibleDelta =
    Math.abs(translateX) > PPTX_ZOOM_MOTION_MIN_TRANSLATE_PX ||
    Math.abs(translateY) > PPTX_ZOOM_MOTION_MIN_TRANSLATE_PX ||
    Math.abs(1 - scaleX) > PPTX_ZOOM_MOTION_MIN_SCALE_DELTA ||
    Math.abs(1 - scaleY) > PPTX_ZOOM_MOTION_MIN_SCALE_DELTA;
  if (!hasVisibleDelta) return null;

  // Re-express the FLIP about the viewport center instead of the canvas's
  // top-left: the canvas is the full deck (potentially hundreds of thousands
  // of px tall), and a scale that far from its origin runs into GPU float
  // precision. Anchoring at the viewport keeps the rasterized region's
  // coordinates small; the mapping is identical.
  const originX = getViewportCenterX(viewportElement) - currentRect.left;
  const originY =
    viewportElement.getBoundingClientRect().top +
    Math.max(0, viewportElement.clientHeight) / 2 -
    currentRect.top;
  const anchoredTranslateX = translateX + (scaleX - 1) * originX;
  const anchoredTranslateY = translateY + (scaleY - 1) * originY;

  let cleanupTimeout: ReturnType<typeof setTimeout> | null = null;
  let startFrame = 0;
  let finished = false;
  const finish = () => {
    if (finished) return;
    finished = true;
    if (startFrame !== 0) cancelAnimationFrame(startFrame);
    if (cleanupTimeout !== null) clearTimeout(cleanupTimeout);
    removeInterruptListeners();
    visualLayer.style.transition = "";
    visualLayer.style.transform = "";
    visualLayer.style.transformOrigin = "";
    visualLayer.style.willChange = "";
  };
  // A user gesture mid-relax snaps to the committed endpoint: layout and
  // scroll already landed in the zoom's own commit, so clearing the transform
  // is always safe — and content must never keep gliding under a live scroll.
  // (Gesture events only; the zoom's own programmatic scroll writes do not
  // fire these.)
  const removeInterruptListeners = attachPptxZoomInterruptListeners(
    viewportElement,
    () => finish(),
  );

  visualLayer.style.transition = "none";
  visualLayer.style.transformOrigin = `${originX}px ${originY}px`;
  visualLayer.style.transform = `translate3d(${anchoredTranslateX}px, ${anchoredTranslateY}px, 0px) scale(${scaleX}, ${scaleY})`;
  visualLayer.style.willChange = "transform";

  startFrame = requestAnimationFrame(() => {
    startFrame = 0;
    if (finished) return;
    visualLayer.style.transition = `transform ${PPTX_ZOOM_MOTION_DURATION_MS}ms ${PPTX_ZOOM_MOTION_EASING}`;
    visualLayer.style.transform = "translate3d(0px, 0px, 0px) scale(1, 1)";
  });
  cleanupTimeout = setTimeout(finish, PPTX_ZOOM_MOTION_CLEANUP_MS);

  return finish;
}

function attachPptxZoomInterruptListeners(
  viewportElement: HTMLDivElement,
  interrupt: () => void,
) {
  if (typeof viewportElement.addEventListener !== "function") return () => {};
  const events = ["wheel", "touchstart", "pointerdown", "keydown"] as const;
  for (const event of events) {
    viewportElement.addEventListener(event, interrupt, { passive: true });
  }
  return () => {
    for (const event of events) {
      viewportElement.removeEventListener(event, interrupt);
    }
  };
}

function getPptxZoomSlideAtOffset(layout: PptxZoomSlideLayout, offset: number) {
  if (layout.slideCount <= 1 || layout.slideStride <= 0) return 1;
  const slideIndex = Math.floor(
    (offset - layout.slideTopPadding) / layout.slideStride,
  );
  return clamp(slideIndex + 1, 1, layout.slideCount);
}

function getPptxZoomSlideTop(layout: PptxZoomSlideLayout, slideIndex: number) {
  return layout.slideTopPadding + slideIndex * layout.slideStride;
}

function findPptxZoomStage(viewportElement: HTMLDivElement) {
  if (typeof viewportElement.querySelector !== "function") return null;
  return viewportElement.querySelector<HTMLElement>(PPTX_ZOOM_STAGE_SELECTOR);
}

function findPptxZoomVisualLayer(viewportElement: HTMLDivElement) {
  if (typeof viewportElement.querySelector !== "function") return null;
  return viewportElement.querySelector<HTMLElement>(
    PPTX_ZOOM_VISUAL_LAYER_SELECTOR,
  );
}

function getViewportCenterX(viewportElement: HTMLDivElement) {
  return (
    viewportElement.getBoundingClientRect().left +
    Math.max(0, viewportElement.clientWidth) / 2
  );
}

function getViewportCenterY(viewportElement: HTMLDivElement) {
  return (
    viewportElement.getBoundingClientRect().top +
    Math.max(0, viewportElement.clientHeight) / 2
  );
}

// True when one axis is pinned while the other rescales — the paged-scroll
// signature — or when the two ratios are so far apart that the stage box
// cannot be tracking the content at all.
function hasDetachedPptxZoomAxes(scaleX: number, scaleY: number) {
  const inlineDelta = Math.abs(scaleX - 1);
  const blockDelta = Math.abs(scaleY - 1);
  const frozenAxis =
    (blockDelta < PPTX_ZOOM_MOTION_AXIS_FROZEN_DELTA &&
      inlineDelta > PPTX_ZOOM_MOTION_AXIS_MOVED_DELTA) ||
    (inlineDelta < PPTX_ZOOM_MOTION_AXIS_FROZEN_DELTA &&
      blockDelta > PPTX_ZOOM_MOTION_AXIS_MOVED_DELTA);
  return (
    frozenAxis ||
    Math.abs(scaleX - scaleY) >
      PPTX_ZOOM_MOTION_AXIS_MISMATCH_RATIO * Math.max(scaleX, scaleY)
  );
}

function readElementRect(element: HTMLElement | null) {
  if (!element || typeof element.getBoundingClientRect !== "function") {
    return null;
  }
  const rect = element.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0 ? rect : null;
}

function prefersReducedMotion() {
  return (
    typeof matchMedia === "function" &&
    matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

"use client";

import * as React from "react";

import { normalizePptxScale } from "./pptx-viewer-core";

type PptxZoomState =
  | { mode: "fit" }
  | {
      mode: "manual";
      value: number;
    };

export interface PptxZoomInput {
  controlledScale?: number;
  defaultScale?: number;
  fitScale: number;
  onScaleChange?: (scale: number | null) => void;
}

export function usePptxZoom({
  controlledScale,
  defaultScale,
  fitScale,
  onScaleChange,
}: PptxZoomInput) {
  const [zoomState, setZoomState] = React.useState<PptxZoomState>(() =>
    defaultScale == null
      ? { mode: "fit" }
      : { mode: "manual", value: normalizePptxScale(defaultScale) },
  );

  const isScaleControlled = controlledScale !== undefined;
  const normalizedControlledScale = isScaleControlled
    ? normalizePptxScale(controlledScale)
    : undefined;
  const zoomScale =
    normalizedControlledScale ??
    (zoomState.mode === "manual" ? zoomState.value : fitScale);
  const isFitWidth = !isScaleControlled && zoomState.mode === "fit";
  const scaleControlsDisabled = isScaleControlled && !onScaleChange;

  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      const normalized =
        nextScale == null ? null : normalizePptxScale(nextScale);
      if (isScaleControlled) {
        onScaleChange?.(normalized);
        return;
      }
      setZoomState(
        normalized == null
          ? { mode: "fit" }
          : { mode: "manual", value: normalized },
      );
    },
    [isScaleControlled, onScaleChange],
  );

  return { isFitWidth, scaleControlsDisabled, setViewerScale, zoomScale };
}

import type {
  ViewerContentBytes,
  ViewerContentIdentity,
} from "@/lib/viewer-resource";

import {
  DisposableLruCache,
  PptxBitmapEntry,
  type Disposable,
} from "./pptx-viewer-cache";
import {
  getPptxBitmapCacheKey,
  type PptxBitmapCacheInput,
  type PptxSize,
  type PptxSlideRenderPriority,
  type PptxSourceLoadTiming,
} from "./pptx-viewer-core";
import {
  createPptxRenderer,
  PptxRendererError,
  type PptxRenderer,
} from "./pptx-viewer-renderer";

const PPTX_SOURCE_CACHE_MAX = 4;
const PPTX_SOURCE_TIMING_CACHE_MAX = 32;
const PPTX_BITMAP_CACHE_MAX = 8;
const PPTX_BITMAP_CACHE_MAX_PIXELS = 24_000_000;

export type PptxSourceRelease = () => void;

export interface PptxSourceRenderInput extends PptxBitmapCacheInput {
  canvas: HTMLCanvasElement;
  isLive?: () => boolean;
  priority?: PptxSlideRenderPriority;
}

export interface PptxSourceDrawCachedBitmapInput extends PptxBitmapCacheInput {
  canvas: HTMLCanvasElement;
}

export type PptxRenderResult =
  | { status: "rendered" }
  | { status: "cancelled" }
  | { status: "failed"; error: PptxRendererError };

export interface PptxSource extends Disposable {
  slideCount: number;
  baseSize: PptxSize;
  drawCachedBitmap(
    input: PptxSourceDrawCachedBitmapInput,
  ): PptxRenderResult | null;
  renderSlide(input: PptxSourceRenderInput): Promise<PptxRenderResult>;
  hasBitmap(input: PptxBitmapCacheInput): boolean;
  retain(): PptxSourceRelease;
}

class RendererSource implements PptxSource {
  readonly slideCount: number;
  readonly baseSize: PptxSize;

  private readonly bitmaps = new DisposableLruCache<string, PptxBitmapEntry>(
    PPTX_BITMAP_CACHE_MAX,
    {
      maxCost: PPTX_BITMAP_CACHE_MAX_PIXELS,
      getCost: (entry) => entry.pixelCount,
    },
  );
  private queue: PptxQueuedRender[] = [];
  private isRendering = false;
  private nextSequence = 1;
  private bitmapSnapshots = new Map<string, Promise<void>>();
  private retainCount = 0;
  private disposeRequested = false;
  private disposed = false;

  constructor(private readonly renderer: PptxRenderer) {
    this.slideCount = renderer.slideCount;
    this.baseSize = renderer.baseSize;
  }

  hasBitmap(input: PptxBitmapCacheInput) {
    if (this.disposed) return false;
    return this.bitmaps.get(getPptxBitmapCacheKey(input)) !== undefined;
  }

  drawCachedBitmap(
    input: PptxSourceDrawCachedBitmapInput,
  ): PptxRenderResult | null {
    if (this.disposed) return null;
    const cached = this.bitmaps.get(getPptxBitmapCacheKey(input));
    if (!cached) return null;
    return drawPptxBitmap(input.canvas, cached.bitmap);
  }

  renderSlide(input: PptxSourceRenderInput): Promise<PptxRenderResult> {
    if (this.disposed) {
      return Promise.resolve({
        status: "failed",
        error: new PptxRendererError(
          "disposed",
          "Presentation source was disposed.",
        ),
      });
    }
    if (!isValidSlideIndex(input.slideIndex, this.slideCount)) {
      return Promise.resolve({
        status: "failed",
        error: new PptxRendererError(
          "index_out_of_range",
          `Slide ${input.slideIndex + 1} is outside the presentation.`,
        ),
      });
    }
    if (!isValidRenderScale(input.renderScale)) {
      return Promise.resolve({
        status: "failed",
        error: new PptxRendererError(
          "bounds",
          "Render scale must be a positive finite number.",
        ),
      });
    }

    const bitmapKey = getPptxBitmapCacheKey(input);
    if (this.hasBitmap(input)) {
      if (!isRenderLive(input)) return Promise.resolve({ status: "cancelled" });
      const cached = this.drawCachedBitmap(input);
      if (cached) return Promise.resolve(cached);
    }

    const snapshot = this.bitmapSnapshots.get(bitmapKey);
    if (snapshot) return this.renderAfterSnapshot(input, snapshot);

    return new Promise<PptxRenderResult>((resolve) => {
      this.queue.push({
        bitmapKey,
        input,
        resolve,
        sequence: this.nextSequence,
      });
      this.nextSequence += 1;
      this.pumpQueue();
    });
  }

  retain(): PptxSourceRelease {
    if (this.disposed) return () => {};
    this.retainCount += 1;
    let hasReleased = false;
    return () => {
      if (hasReleased) return;
      hasReleased = true;
      this.retainCount -= 1;
      if (this.retainCount === 0 && this.disposeRequested) this.close();
    };
  }

  dispose() {
    this.disposeRequested = true;
    if (this.retainCount === 0) this.close();
  }

  private close() {
    if (this.disposed) return;
    this.disposed = true;
    for (const task of this.queue.splice(0))
      task.resolve({ status: "cancelled" });
    this.bitmapSnapshots.clear();
    this.bitmaps.clear();
    this.renderer.dispose();
  }

  private pumpQueue() {
    if (this.isRendering) return;
    this.isRendering = true;
    void this.drainQueue();
  }

  private async drainQueue() {
    try {
      while (!this.disposed && this.queue.length > 0) {
        const task = this.takeNextTask();
        if (!task) break;
        await this.runTask(task);
      }
    } finally {
      this.isRendering = false;
      if (!this.disposed && this.queue.length > 0) this.pumpQueue();
    }
  }

  private takeNextTask() {
    this.pruneStaleQueuedTasks();

    let bestIndex = -1;
    let bestRank: PptxRenderRank | null = null;
    for (let index = 0; index < this.queue.length; index += 1) {
      const task = this.queue[index];
      if (!task) continue;
      const rank = getRenderRank(task);
      if (!bestRank || compareRenderRanks(rank, bestRank) < 0) {
        bestRank = rank;
        bestIndex = index;
      }
    }
    if (bestIndex < 0) return null;
    const [task] = this.queue.splice(bestIndex, 1);
    return task ?? null;
  }

  private pruneStaleQueuedTasks() {
    const liveQueue: PptxQueuedRender[] = [];
    for (const task of this.queue) {
      if (isRenderLive(task.input)) {
        liveQueue.push(task);
      } else {
        task.resolve({ status: "cancelled" });
      }
    }
    this.queue = liveQueue;
  }

  private async runTask(task: PptxQueuedRender) {
    if (this.disposed) {
      task.resolve({ status: "cancelled" });
      return;
    }
    if (!isRenderLive(task.input)) {
      task.resolve({ status: "cancelled" });
      return;
    }

    const cached = this.drawCachedBitmap(task.input);
    if (cached) {
      task.resolve(cached);
      return;
    }

    const pendingSnapshot = this.bitmapSnapshots.get(task.bitmapKey);
    if (pendingSnapshot) {
      task.resolve(this.renderAfterSnapshot(task.input, pendingSnapshot));
      return;
    }

    try {
      await this.renderer.renderSlide(task.input);
    } catch (error) {
      if (this.disposed || !isRenderLive(task.input)) {
        task.resolve({ status: "cancelled" });
        return;
      }
      task.resolve({
        status: "failed",
        error: normalizeRendererError(error),
      });
      return;
    }

    if (this.disposed || !isRenderLive(task.input)) {
      task.resolve({ status: "cancelled" });
      return;
    }

    const snapshot = this.scheduleBitmapSnapshot(task);
    this.resolveQueuedBitmapDuplicates(task.bitmapKey, snapshot);
    task.resolve({ status: "rendered" });
  }

  private renderAfterSnapshot(
    input: PptxSourceRenderInput,
    snapshot: Promise<void>,
  ): Promise<PptxRenderResult> {
    return snapshot.then(
      () => {
        if (this.disposed) return { status: "cancelled" };
        if (!isRenderLive(input)) return { status: "cancelled" };
        const cached = this.drawCachedBitmap(input);
        if (cached) return cached;
        return this.renderSlide(input);
      },
      () => {
        if (this.disposed) return { status: "cancelled" };
        if (!isRenderLive(input)) return { status: "cancelled" };
        return this.renderSlide(input);
      },
    );
  }

  private scheduleBitmapSnapshot(task: PptxQueuedRender) {
    const snapshot = this.captureBitmap(task);
    this.bitmapSnapshots.set(task.bitmapKey, snapshot);
    snapshot.finally(() => {
      if (this.bitmapSnapshots.get(task.bitmapKey) === snapshot) {
        this.bitmapSnapshots.delete(task.bitmapKey);
      }
    });
    return snapshot;
  }

  private resolveQueuedBitmapDuplicates(
    bitmapKey: string,
    snapshot: Promise<void>,
  ) {
    const remainingQueue: PptxQueuedRender[] = [];
    for (const queued of this.queue) {
      if (queued.bitmapKey !== bitmapKey) {
        remainingQueue.push(queued);
      } else if (isRenderLive(queued.input)) {
        queued.resolve(this.renderAfterSnapshot(queued.input, snapshot));
      } else {
        queued.resolve({ status: "cancelled" });
      }
    }
    this.queue = remainingQueue;
  }

  private async captureBitmap(task: PptxQueuedRender) {
    let bitmap: ImageBitmap | null = null;
    try {
      bitmap = await createImageBitmap(task.input.canvas);
      if (this.disposed || !isRenderLive(task.input)) {
        bitmap.close();
        return;
      }
      this.bitmaps.set(task.bitmapKey, new PptxBitmapEntry(bitmap));
      bitmap = null;
    } catch {
      if (bitmap) bitmap.close();
      /* Snapshot unsupported: the slide still rendered, just without cache. */
    }
  }
}

type PptxQueuedRender = {
  bitmapKey: string;
  input: PptxSourceRenderInput;
  resolve: (result: PptxRenderResult | PromiseLike<PptxRenderResult>) => void;
  sequence: number;
};

type PptxRenderRank = {
  visibility: number;
  distance: number;
  sequence: number;
};

function getRenderRank(task: PptxQueuedRender): PptxRenderRank {
  const priority = task.input.priority;
  return {
    visibility: priority?.isCurrentSlide
      ? 0
      : priority?.isInViewport
        ? 1
        : priority?.isScrollLead
          ? 2
          : 3,
    distance:
      priority && Number.isFinite(priority.distanceFromReadingMarker)
        ? Math.max(0, priority.distanceFromReadingMarker)
        : Number.MAX_SAFE_INTEGER,
    sequence: task.sequence,
  };
}

function compareRenderRanks(a: PptxRenderRank, b: PptxRenderRank) {
  if (a.visibility !== b.visibility) return a.visibility - b.visibility;
  if (a.distance !== b.distance) return a.distance - b.distance;
  return a.sequence - b.sequence;
}

class SourceCacheEntry implements Disposable {
  source?: PptxSource;
  loadTiming?: PptxSourceLoadTiming;
  disposed = false;
  private settled = false;
  private readonly loadTimingSubscribers = new Set<
    (timing: PptxSourceLoadTiming) => void
  >();

  constructor(readonly promise: Promise<PptxSource>) {
    promise.then(
      (source) => {
        this.settled = true;
        this.source = source;
        if (this.disposed) source.dispose();
      },
      () => {
        this.settled = true;
        /* rejected entries are removed by getPptxSource */
      },
    );
  }

  /**
   * A still-loading entry must not be evicted: dispose() cannot act on a source
   * that has not resolved yet, so an evicted-pending entry would leak its
   * renderer once the load completes (and a Suspense retry would create a
   * duplicate). Pin it until the load settles.
   */
  isEvictable() {
    return this.settled || this.disposed;
  }

  dispose() {
    this.loadTimingSubscribers.clear();
    this.disposed = true;
    this.source?.dispose();
  }

  disposeWhenResolved() {
    this.disposed = true;
    this.loadTimingSubscribers.clear();
    this.source?.dispose();
  }

  setLoadTiming(timing: PptxSourceLoadTiming) {
    this.loadTiming = timing;
    for (const subscriber of this.loadTimingSubscribers) {
      notifyLoadTimingSubscriber(subscriber, timing);
    }
  }

  subscribeLoadTiming(callback: (timing: PptxSourceLoadTiming) => void) {
    this.loadTimingSubscribers.add(callback);
    if (this.loadTiming) {
      const loadTiming = this.loadTiming;
      setTimeout(() => {
        if (this.loadTimingSubscribers.has(callback)) {
          notifyLoadTimingSubscriber(callback, loadTiming);
        }
      }, 0);
    }
    return () => {
      this.loadTimingSubscribers.delete(callback);
    };
  }
}

function notifyLoadTimingSubscriber(
  subscriber: (timing: PptxSourceLoadTiming) => void,
  timing: PptxSourceLoadTiming,
) {
  try {
    subscriber(timing);
  } catch {
    /* Instrumentation callbacks must not affect viewer loading. */
  }
}

const sourceCache = new DisposableLruCache<string, SourceCacheEntry>(
  PPTX_SOURCE_CACHE_MAX,
);
const sourceLoadTimingCache = new Map<string, PptxSourceLoadTiming>();

export function getPptxSource(
  content: ViewerContentBytes,
): Promise<PptxSource> {
  const loadKey = content.key;
  const cached = sourceCache.get(loadKey);
  if (cached) return cached.promise;

  sourceLoadTimingCache.delete(loadKey);

  const pendingEntry: { current?: SourceCacheEntry } = {};
  let pendingLoadTiming: PptxSourceLoadTiming | null = null;
  const handleLoadTiming = (timing: PptxSourceLoadTiming) => {
    rememberSourceLoadTiming(loadKey, timing);
    if (pendingEntry.current) {
      pendingEntry.current.setLoadTiming(timing);
    } else {
      pendingLoadTiming = timing;
    }
  };
  const promise = createPptxRenderer(content, handleLoadTiming).then(
    (renderer) => new RendererSource(renderer),
    (error) => {
      scheduleFailedSourceEviction(loadKey, pendingEntry.current);
      throw error;
    },
  );
  const entry = new SourceCacheEntry(promise);
  pendingEntry.current = entry;
  if (pendingLoadTiming) entry.setLoadTiming(pendingLoadTiming);
  sourceCache.set(loadKey, entry);
  return entry.promise;
}

export function subscribePptxSourceLoadTiming(
  content: ViewerContentIdentity,
  callback: (timing: PptxSourceLoadTiming) => void,
) {
  const loadKey = content.key;
  const entry = sourceCache.get(loadKey);
  if (!entry) return subscribeCachedSourceLoadTiming(loadKey, callback);
  return entry.subscribeLoadTiming(callback);
}

export function evictPptxSource(content: ViewerContentIdentity) {
  sourceLoadTimingCache.delete(content.key);
  sourceCache.delete(content.key);
}

function subscribeCachedSourceLoadTiming(
  loadKey: string,
  callback: (timing: PptxSourceLoadTiming) => void,
) {
  const loadTiming = sourceLoadTimingCache.get(loadKey);
  if (!loadTiming) return () => {};
  let isSubscribed = true;
  setTimeout(() => {
    if (isSubscribed) notifyLoadTimingSubscriber(callback, loadTiming);
  }, 0);
  return () => {
    isSubscribed = false;
  };
}

function rememberSourceLoadTiming(
  loadKey: string,
  timing: PptxSourceLoadTiming,
) {
  sourceLoadTimingCache.delete(loadKey);
  sourceLoadTimingCache.set(loadKey, timing);
  while (sourceLoadTimingCache.size > PPTX_SOURCE_TIMING_CACHE_MAX) {
    const oldestLoadKey = sourceLoadTimingCache.keys().next().value;
    if (!oldestLoadKey) return;
    sourceLoadTimingCache.delete(oldestLoadKey);
  }
}

function scheduleFailedSourceEviction(
  loadKey: string,
  entry: SourceCacheEntry | undefined,
) {
  if (!entry) return;
  setTimeout(() => {
    if (sourceCache.get(loadKey) === entry) sourceCache.delete(loadKey);
  }, 0);
}

export function disposePptxSourceCache() {
  for (const entry of sourceCache.snapshotValues()) {
    entry.disposeWhenResolved();
  }
  sourceCache.clear();
  sourceLoadTimingCache.clear();
}

function isRenderLive({ isLive }: Pick<PptxSourceRenderInput, "isLive">) {
  try {
    return !isLive || isLive();
  } catch {
    return false;
  }
}

function isValidSlideIndex(slideIndex: number, slideCount: number) {
  return (
    Number.isInteger(slideIndex) && slideIndex >= 0 && slideIndex < slideCount
  );
}

function isValidRenderScale(renderScale: number) {
  return Number.isFinite(renderScale) && renderScale > 0;
}

function drawPptxBitmap(
  canvas: HTMLCanvasElement,
  bitmap: ImageBitmap,
): PptxRenderResult {
  try {
    drawBitmap(canvas, bitmap);
    return { status: "rendered" };
  } catch (error) {
    return {
      status: "failed",
      error: new PptxRendererError(
        "render_failed",
        "Failed to draw cached slide bitmap.",
        error,
      ),
    };
  }
}

function drawBitmap(canvas: HTMLCanvasElement, bitmap: ImageBitmap) {
  canvas.width = bitmap.width;
  canvas.height = bitmap.height;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Canvas 2D context is unavailable.");
  context.drawImage(bitmap, 0, 0);
}

function normalizeRendererError(error: unknown) {
  if (error instanceof PptxRendererError) return error;
  return new PptxRendererError(
    "render_failed",
    "Failed to render slide.",
    error,
  );
}

"use client";

import * as React from "react";
import { createRoot, type Root } from "react-dom/client";
import { useMountEffect } from "@/hooks/use-mount-effect";

import { Skeleton } from "@/components/ui/skeleton";

import {
  getPptxRenderPixelRatio,
  getScaledSlideSize,
  getVisibleSlideSize,
  type PptxSize,
  type PptxSlideOverlayProps,
  type PptxSlideRenderPriority,
  type PptxSlideRenderTiming,
} from "./pptx-viewer-core";
import { type PptxScrollActivity } from "./pptx-viewer-scroll";
import { type PptxSource } from "./pptx-viewer-source";
import {
  createPptxSlideLayout,
  getPptxRenderedSlideWindow,
  getPptxRenderSlides,
  getPptxSlideTop,
  readPptxScrollMetrics,
  PPTX_READING_MARKER_RATIO,
  PPTX_RENDER_WINDOW_OVERSCAN_PX,
  type PptxSlideLayout,
  type PptxScrollMetrics,
  type PptxVirtualSlide,
} from "./pptx-viewer-visible-slide";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

type SlideRenderState = "idle" | "rendering" | "rendered" | "failed";
type PptxScrollDirection = -1 | 0 | 1;

export const PPTX_SLIDE_GAP = 16;
export const PPTX_SLIDE_PADDING = 16;
const PPTX_TRANSITION_WINDOW_RELEASE_MS = 260;
const PPTX_UPWARD_SCROLL_LEAD_PX = PPTX_RENDER_WINDOW_OVERSCAN_PX;

export interface PptxSlideScrollerProps {
  source: PptxSource;
  zoomScale: number;
  rotation: number;
  layout?: PptxSlideLayout;
  eager: boolean;
  activity: PptxScrollActivity;
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode;
  onSlideRenderTiming?: (timing: PptxSlideRenderTiming) => void;
  containerRef: React.Ref<HTMLDivElement>;
  documentSurfaceRef?: React.Ref<HTMLDivElement>;
  viewportRef: React.Ref<HTMLDivElement>;
  getScrollMetrics?: () => PptxScrollMetrics;
  /** The slide column is at its fit-width scale (the shell motion's domain). */
  isFitWidth?: boolean;
  isTransitioning?: boolean;
  onScroll: () => void;
}

export function PptxSlideScroller({
  source,
  zoomScale,
  rotation,
  layout: providedLayout,
  eager,
  activity,
  renderSlideOverlay,
  onSlideRenderTiming,
  containerRef,
  documentSurfaceRef,
  viewportRef,
  getScrollMetrics,
  isFitWidth = true,
  isTransitioning = false,
  onScroll,
}: PptxSlideScrollerProps) {
  const layout = React.useMemo(
    () =>
      providedLayout ??
      createPptxSlideLayout({
        baseSize: source.baseSize,
        zoomScale,
        rotation,
        slideCount: source.slideCount,
        slideGap: PPTX_SLIDE_GAP,
        slidePadding: PPTX_SLIDE_PADDING,
      }),
    [providedLayout, rotation, source.baseSize, source.slideCount, zoomScale],
  );
  const canvasRef = React.useRef<HTMLDivElement | null>(null);
  const projectionFrameRef = React.useRef<number | null>(null);
  const projectionCacheRef = React.useRef<PptxSlideProjectionCache>({
    canvas: null,
    hasMeasuredScroll: false,
    lastScrollDirection: 0,
    lastScrollTop: 0,
    resetKey: "",
    slides: new Map(),
    window: null,
  });
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null);
  const projectSlidesRef = React.useRef<() => void>(() => {});
  const isTransitioningRef = React.useRef(isTransitioning);
  const transitionWindowReleaseTimerRef = React.useRef<number | null>(null);
  isTransitioningRef.current = isTransitioning;
  const layoutResetKey = `${layout.slideCount}:${layout.slideWidth}:${layout.slideHeight}:${layout.slideStride}:${layout.totalHeight}:${zoomScale}:${rotation}`;

  const projectSlides = React.useCallback(() => {
    projectionFrameRef.current = null;
    const result = projectPptxSlides({
      activity,
      cache: projectionCacheRef.current,
      canvas: canvasRef.current,
      eager,
      getScrollMetrics,
      isTransitioning: isTransitioningRef.current,
      layout,
      onSlideRenderTiming,
      renderSlideOverlay,
      resetKey: layoutResetKey,
      rotation,
      source,
      viewport: viewportElementRef.current,
      zoomScale,
    });
    if (
      result.fillOverscanNextFrame &&
      projectionFrameRef.current === null &&
      typeof requestAnimationFrame === "function"
    ) {
      projectionFrameRef.current = requestAnimationFrame(() =>
        projectSlidesRef.current(),
      );
    }
  }, [
    activity,
    eager,
    getScrollMetrics,
    layout,
    layoutResetKey,
    onSlideRenderTiming,
    renderSlideOverlay,
    rotation,
    source,
    zoomScale,
  ]);
  projectSlidesRef.current = projectSlides;

  const scheduleProjectSlides = React.useCallback(() => {
    if (projectionFrameRef.current !== null) return;
    if (typeof requestAnimationFrame !== "function") {
      projectSlides();
      return;
    }
    projectionFrameRef.current = requestAnimationFrame(projectSlides);
  }, [projectSlides]);

  useKeyedLayoutEffect(joinEffectKey([projectSlides]), () => {
    projectSlides();
  });

  const clearTransitionWindowReleaseTimer = React.useCallback(() => {
    if (transitionWindowReleaseTimerRef.current === null) return;
    window.clearTimeout(transitionWindowReleaseTimerRef.current);
    transitionWindowReleaseTimerRef.current = null;
  }, []);

  // The sidebar slide freezes the visible-slide window (see projectPptxSlides).
  // Once the motion settles — scroll rebased to the re-fit layout — re-derive the
  // window after the sampled motion window, so cleanup never reads as motion
  // churn.
  useKeyedLayoutEffect(
    joinEffectKey(["pptx-transition", isTransitioning]),
    () => {
      clearTransitionWindowReleaseTimer();
      if (isTransitioning) return;

      transitionWindowReleaseTimerRef.current = window.setTimeout(() => {
        transitionWindowReleaseTimerRef.current = null;
        projectSlidesRef.current();
      }, PPTX_TRANSITION_WINDOW_RELEASE_MS);
    },
  );

  useMountEffect(() => () => {
    if (
      projectionFrameRef.current !== null &&
      typeof cancelAnimationFrame === "function"
    ) {
      cancelAnimationFrame(projectionFrameRef.current);
    }
    clearTransitionWindowReleaseTimer();
    disposePptxSlideProjectionCache(projectionCacheRef.current);
  });

  const setViewportRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element;
      assignPptxRef(viewportRef, element);
      assignPptxRef(containerRef, element);
    },
    [containerRef, viewportRef],
  );

  const setCanvasRef = React.useCallback((element: HTMLDivElement | null) => {
    canvasRef.current = element;
  }, []);

  const handleScroll = React.useCallback(() => {
    onScroll();
    scheduleProjectSlides();
  }, [onScroll, scheduleProjectSlides]);

  return (
    <div className="size-full min-h-0 flex-1">
      <div
        ref={setViewportRef}
        className="focus-visible:ring-ring focus-visible:ring-offset-background h-full overflow-auto rounded-[inherit] outline-none focus-visible:ring-2 focus-visible:ring-offset-1"
        data-slot="scroll-area-viewport"
        onScroll={handleScroll}
        style={{ overflowAnchor: "none" }}
      >
        {/* The clip exists for ONE state: a fit-width shell slide, where the
            kernel's counter-transform paints the surface past its committed
            box, and that visual overflow would otherwise inflate the
            scroller's scrollHeight and drag a max-clamped scroll position
            down frame by frame as the transform relaxes. Every other state
            must NOT clip: a zoomed-in surface's inline overflow IS the
            horizontal scroll range (an unconditional clip froze scrollWidth
            at the viewport width and made zoomed decks horizontally
            unscrollable), and a zoom relax's enlarged opening frame must not
            be cut at the committed box. At fit-width the surface fits the
            layout width, so the active clip can never eat scrollable
            overflow. */}
        {/* Flex column so the surface's block-axis auto margin has free space
            to split once a zoomed-out deck is shorter than the pane. */}
        <div
          className={`flex min-h-full flex-col ${
            isTransitioning && isFitWidth ? "overflow-clip" : "overflow-visible"
          }`}
        >
          <div
            ref={documentSurfaceRef}
            className={`relative mx-auto min-w-0 shrink-0 ${
              // Block-axis centring only outside fit-width: at fit-width a
              // pane resize re-fits the slides, and half of that height delta
              // is motion the shell transform does not model. Zoomed, that
              // transform is identity and the height is pane-independent.
              isFitWidth ? "" : "my-auto"
            }`}
            data-slot="pptx-viewer-document-surface"
            style={{
              contain: "layout style",
              minWidth: layout.slideWidth,
              width: layout.slideWidth,
            }}
          >
            <div
              ref={setCanvasRef}
              className="relative h-full w-full"
              data-slot="pptx-slide-virtual-canvas"
            />
          </div>
        </div>
      </div>
    </div>
  );
}

function PptxSlideFrame({
  source,
  slideIndex,
  layoutZoomScale,
  rasterZoomScale,
  rotation,
  eager,
  activity,
  renderSlideOverlay,
  getSlideRenderTiming,
  isProjectedLive,
  priority,
  shouldRenderImmediately,
}: {
  source: PptxSource;
  slideIndex: number;
  // The scale the slide BOX is laid out at (the target of the current motion,
  // re-fit every commit). Drives the DOM box the shell transform reprojects.
  layoutZoomScale: number;
  // The scale the CANVAS bitmap is rastered at. Held frozen through a
  // transition so the box can re-fit without a re-raster; the bitmap is
  // CSS-scaled into the box.
  rasterZoomScale: number;
  rotation: number;
  eager: boolean;
  activity: PptxScrollActivity;
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode;
  getSlideRenderTiming?: () =>
    | ((timing: PptxSlideRenderTiming) => void)
    | undefined;
  isProjectedLive?: () => boolean;
  priority: PptxSlideRenderPriority;
  shouldRenderImmediately: boolean;
}) {
  const boxSize = getScaledSlideSize(source.baseSize, layoutZoomScale);
  const visibleSize = getVisibleSlideSize(boxSize, rotation);

  return (
    <div
      className="ring-border relative shadow-sm ring-1"
      style={{ width: visibleSize.width, height: visibleSize.height }}
      data-slot="pptx-slide"
      data-slide-number={slideIndex + 1}
    >
      <div
        className="absolute top-1/2 left-1/2"
        style={{
          width: boxSize.width,
          height: boxSize.height,
          transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
        }}
      >
        <PptxSlideCanvas
          source={source}
          slideIndex={slideIndex}
          layoutZoomScale={layoutZoomScale}
          rasterZoomScale={rasterZoomScale}
          eager={eager}
          activity={activity}
          getSlideRenderTiming={getSlideRenderTiming}
          isProjectedLive={isProjectedLive}
          priority={priority}
          shouldRenderImmediately={shouldRenderImmediately}
        />
      </div>
      {renderSlideOverlay ? (
        <PptxSlideOverlay
          slideNumber={slideIndex + 1}
          visibleSize={visibleSize}
          zoomScale={layoutZoomScale}
          rotation={rotation}
          renderSlideOverlay={renderSlideOverlay}
        />
      ) : null}
    </div>
  );
}

function PptxSlideCanvas({
  source,
  slideIndex,
  layoutZoomScale,
  rasterZoomScale,
  eager,
  activity,
  getSlideRenderTiming,
  isProjectedLive,
  priority,
  shouldRenderImmediately,
}: {
  source: PptxSource;
  slideIndex: number;
  layoutZoomScale: number;
  rasterZoomScale: number;
  eager: boolean;
  activity: PptxScrollActivity;
  getSlideRenderTiming?: () =>
    | ((timing: PptxSlideRenderTiming) => void)
    | undefined;
  isProjectedLive?: () => boolean;
  priority: PptxSlideRenderPriority;
  shouldRenderImmediately: boolean;
}) {
  const rawDpr = typeof window !== "undefined" ? window.devicePixelRatio : 1;
  const pixelRatio = getPptxRenderPixelRatio(rawDpr);
  // Display size follows the box (target) scale; the backing store is rastered
  // at the raster (possibly frozen) scale and CSS-scaled into it.
  const slideSize = getScaledSlideSize(source.baseSize, layoutZoomScale);
  const [renderState, setRenderState] =
    React.useState<SlideRenderState>("idle");
  const canvasElementRef = React.useRef<HTMLCanvasElement | null>(null);

  const canvasRef = React.useCallback((canvas: HTMLCanvasElement | null) => {
    canvasElementRef.current = canvas;
  }, []);

  // Keyed on the RASTER scale (and stable priority primitives), never the
  // layout scale — re-fitting the box to a new target must not re-raster the
  // held bitmap. distanceFromReadingMarker is a scheduling hint only, so its
  // per-frame drift is deliberately excluded from the raster key.
  useKeyedLayoutEffect(
    joinEffectKey([
      activity,
      eager,
      getSlideRenderTiming,
      isProjectedLive,
      pixelRatio,
      priority.isCurrentSlide,
      priority.isInViewport,
      priority.isScrollLead,
      shouldRenderImmediately,
      rasterZoomScale,
      slideIndex,
      source,
    ]),
    () => {
      const canvas = canvasElementRef.current;
      if (!canvas) return;

      let cancelled = false;
      const renderScale = rasterZoomScale * pixelRatio;
      if (isProjectedLive && !isProjectedLive()) return;

      const cachedResult = source.drawCachedBitmap({
        canvas,
        renderScale,
        slideIndex,
      });
      if (cachedResult) {
        notifySlideRenderTiming(getSlideRenderTiming?.(), {
          cached: true,
          durationMs: 0,
          pixelRatio,
          renderScale,
          slideNumber: slideIndex + 1,
          status: cachedResult.status,
        });
        if (cachedResult.status !== "cancelled") {
          setRenderState(
            cachedResult.status === "failed" ? "failed" : "rendered",
          );
        }
        return () => {
          cancelled = true;
        };
      }

      setRenderState("rendering");

      const start = () => {
        if (isProjectedLive && !isProjectedLive()) return;
        const startedAt = now();
        const startedCached = source.hasBitmap({ slideIndex, renderScale });
        const cachedResult = source.drawCachedBitmap({
          canvas,
          renderScale,
          slideIndex,
        });
        if (cachedResult) {
          notifySlideRenderTiming(getSlideRenderTiming?.(), {
            cached: true,
            durationMs: now() - startedAt,
            pixelRatio,
            renderScale,
            slideNumber: slideIndex + 1,
            status: cachedResult.status,
          });
          if (cachedResult.status !== "cancelled") {
            setRenderState(
              cachedResult.status === "failed" ? "failed" : "rendered",
            );
          }
          return;
        }
        source
          .renderSlide({
            slideIndex,
            canvas,
            renderScale,
            isLive: () => !cancelled,
            priority,
          })
          .then((result) => {
            if (cancelled || (isProjectedLive && !isProjectedLive())) return;
            notifySlideRenderTiming(getSlideRenderTiming?.(), {
              cached: startedCached,
              durationMs: now() - startedAt,
              pixelRatio,
              renderScale,
              slideNumber: slideIndex + 1,
              status: result.status,
            });
            if (result.status === "cancelled") return;
            setRenderState(result.status === "failed" ? "failed" : "rendered");
          })
          .catch(() => {
            if (cancelled || (isProjectedLive && !isProjectedLive())) return;
            notifySlideRenderTiming(getSlideRenderTiming?.(), {
              cached: startedCached,
              durationMs: now() - startedAt,
              pixelRatio,
              renderScale,
              slideNumber: slideIndex + 1,
              status: "failed",
            });
            setRenderState("failed");
          });
      };

      if (shouldRenderImmediately || eager || !activity.isScrolling()) {
        start();
        return () => {
          cancelled = true;
        };
      }

      const off = activity.onIdle(() => {
        if (!cancelled && (!isProjectedLive || isProjectedLive())) start();
      });
      return () => {
        cancelled = true;
        off();
      };
    },
  );

  return (
    <>
      <canvas
        ref={canvasRef}
        style={{ width: slideSize.width, height: slideSize.height }}
        className="block h-full w-full bg-white"
      />
      {renderState === "failed" ? (
        <div className="bg-muted text-muted-foreground absolute inset-0 flex items-center justify-center p-4 text-center text-xs">
          Couldn&apos;t render slide {slideIndex + 1}.
        </div>
      ) : null}
      {renderState !== "rendered" && renderState !== "failed" ? (
        <Skeleton className="pointer-events-none absolute inset-0 rounded-none" />
      ) : null}
    </>
  );
}

function notifySlideRenderTiming(
  callback: ((timing: PptxSlideRenderTiming) => void) | undefined,
  timing: PptxSlideRenderTiming,
) {
  try {
    callback?.(timing);
  } catch {
    /* Instrumentation callbacks must not affect slide rendering. */
  }
}

function now() {
  return typeof performance === "undefined" ? Date.now() : performance.now();
}

type PptxSlideProjectionCache = {
  canvas: HTMLDivElement | null;
  hasMeasuredScroll: boolean;
  lastScrollDirection: PptxScrollDirection;
  lastScrollTop: number;
  resetKey: string;
  slides: Map<number, PptxProjectedSlide>;
  window: PptxSlideProjectionWindow | null;
};

type PptxSlideProjectionResult = {
  fillOverscanNextFrame: boolean;
};

type PptxSlideProjectionWindow = {
  after: HTMLDivElement;
  before: HTMLDivElement;
  content: HTMLDivElement;
  sticky: HTMLDivElement;
};

type PptxProjectedSlide = {
  activity: PptxScrollActivity | null;
  getSlideRenderTiming: () =>
    | ((timing: PptxSlideRenderTiming) => void)
    | undefined;
  isLive: boolean;
  isProjectedLive: () => boolean;
  onSlideRenderTiming:
    | ((timing: PptxSlideRenderTiming) => void)
    | null
    | undefined;
  // The zoom scale the slide's canvas bitmap was last rastered at. The slide's
  // BOX tracks the target layout scale every commit (so the shell transform
  // reprojects it continuously), but its raster is held at this scale through a
  // transition — the frozen bitmap is CSS-scaled to the box, no re-raster.
  rasterZoomScale: number | null;
  renderSlideOverlay:
    | ((props: PptxSlideOverlayProps) => React.ReactNode)
    | null
    | undefined;
  renderKey: string;
  root: Root;
  shell: HTMLElement;
  source: PptxSource | null;
};

const pptxProjectionSourceKeys = new WeakMap<PptxSource, number>();
let nextPptxProjectionSourceKey = 1;

function projectPptxSlides({
  activity,
  cache,
  canvas,
  eager,
  getScrollMetrics,
  isTransitioning,
  layout,
  onSlideRenderTiming,
  renderSlideOverlay,
  resetKey,
  rotation,
  source,
  viewport,
  zoomScale,
}: {
  activity: PptxScrollActivity;
  cache: PptxSlideProjectionCache;
  canvas: HTMLDivElement | null;
  eager: boolean;
  getScrollMetrics?: () => PptxScrollMetrics;
  isTransitioning: boolean;
  layout: PptxSlideLayout;
  onSlideRenderTiming?: (timing: PptxSlideRenderTiming) => void;
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode;
  resetKey: string;
  rotation: number;
  source: PptxSource;
  viewport: HTMLDivElement | null;
  zoomScale: number;
}): PptxSlideProjectionResult {
  if (!canvas) return { fillOverscanNextFrame: false };

  if (cache.canvas !== canvas) {
    disposePptxSlideProjectionCache(cache);
    cache.canvas = canvas;
  }

  const sourceKey = getPptxProjectionSourceKey(source);
  const nextResetKey = `${sourceKey}:${resetKey}`;

  // Slides mounted before the sidebar motion began. Held for the duration of the
  // transition so the fit-width re-fit — which shifts the scroll model under the
  // reader before the shell rebases it — can't churn the reading slide out of the
  // mounted set. While transitioning, use this exact set: unioning with the new
  // live window introduces add/remove churn in the sampled motion window.
  const heldSlideIndexes =
    isTransitioning && cache.slides.size > 0 ? [...cache.slides.keys()] : [];
  const isHoldingTransitionWindow = heldSlideIndexes.length > 0;

  if (cache.resetKey !== nextResetKey) {
    // The fit-width re-fit changes zoomScale (part of the reset key), but the
    // mounted slides stay valid — only their size/position changes, re-patched
    // below. Disposing mid-transition would tear down and remount the reading
    // slide, defeating the hold; keep the cache and adopt the new key in place.
    if (heldSlideIndexes.length === 0) {
      disposePptxSlideProjectionCache(cache);
    }
    cache.resetKey = nextResetKey;
  }

  const viewportHeight =
    viewport?.clientHeight || viewport?.getBoundingClientRect().height || 0;
  const metrics =
    getScrollMetrics?.() ??
    readPptxScrollMetrics({
      scrollPageOffset: 0,
      totalHeight: layout.totalHeight,
      viewportElement: viewport,
    });
  const measuredScrollDirection = getPptxScrollDirection({
    canMeasureDirection: cache.hasMeasuredScroll,
    previousScrollTop: cache.lastScrollTop,
    scrollTop: metrics.scrollTop,
  });
  const scrollDirection =
    measuredScrollDirection === 0
      ? cache.lastScrollDirection
      : measuredScrollDirection;
  if (measuredScrollDirection !== 0) {
    cache.lastScrollDirection = measuredScrollDirection;
  }
  const fitPerfectly = shouldFitPptxPerfectly({
    canFitPerfectly: cache.hasMeasuredScroll,
    previousScrollTop: cache.lastScrollTop,
    scrollTop: metrics.scrollTop,
    viewportHeight: metrics.viewportHeight,
  });
  cache.hasMeasuredScroll = true;
  cache.lastScrollTop = metrics.scrollTop;

  setPptxStyle(canvas, "contain", "layout style");
  setPptxPixelStyle(canvas, "height", metrics.physicalScrollHeight);
  setPptxPixelStyle(canvas, "min-width", layout.slideWidth);
  setPptxPixelStyle(canvas, "width", layout.slideWidth);

  const liveSlides = getPptxRenderSlides({
    fitPerfectly,
    layout,
    scrollTop: metrics.scrollTop,
    viewportHeight: metrics.viewportHeight || viewportHeight,
  });
  const liveSlideIndexes = new Set(
    liveSlides.map((virtualSlide) => virtualSlide.index),
  );
  // Held slides are kept mounted for continuity but must not re-raster: they
  // retain their existing bitmap (rendered at the pre-motion scale) and are
  // disposed once the delayed transition release runs.
  const heldOnlyIndexes = new Set(
    isHoldingTransitionWindow
      ? heldSlideIndexes
      : heldSlideIndexes.filter((index) => !liveSlideIndexes.has(index)),
  );
  const virtualSlides = isHoldingTransitionWindow
    ? getHeldPptxVirtualSlides(heldSlideIndexes, layout)
    : unionPptxVirtualSlides(liveSlides, heldSlideIndexes, layout);
  const renderedWindow = getPptxRenderedSlideWindow({
    layout,
    physicalScrollHeight: metrics.physicalScrollHeight,
    scrollPageOffset: metrics.scrollPageOffset,
    slides: virtualSlides,
    viewportHeight: metrics.viewportHeight || viewportHeight,
  });
  const visibleSlideIndexes = new Set(
    virtualSlides.map((virtualSlide) => virtualSlide.index),
  );
  const projectionWindow = ensurePptxProjectionWindow(cache, canvas);

  for (const [slideIndex, projectedSlide] of cache.slides) {
    if (visibleSlideIndexes.has(slideIndex)) continue;
    disposePptxProjectedSlide(projectedSlide);
    cache.slides.delete(slideIndex);
  }

  if (!renderedWindow) {
    syncPptxProjectionWindow(projectionWindow, {
      afterHeight: metrics.physicalScrollHeight,
      beforeHeight: 0,
      height: 0,
      stickyBottomInset: 0,
      stickyTopInset: 0,
    });
    return { fillOverscanNextFrame: fitPerfectly };
  }

  syncPptxProjectionWindow(projectionWindow, renderedWindow);

  let previousShell: HTMLElement | null = null;
  for (const virtualSlide of renderedWindow.slides) {
    const existingSlide = cache.slides.get(virtualSlide.index);
    const projectedSlide =
      existingSlide ?? createPptxProjectedSlide(virtualSlide);
    patchPptxProjectedSlide(projectedSlide.shell, virtualSlide);
    // A held-only slide that already has a bitmap keeps that bitmap (rastered
    // at its frozen scale) — so the transition adds no raster work — but its
    // BOX still re-fits to the target layout scale. The box drives the shell
    // transform's continuity; freezing the box (as skipping the render did)
    // makes the uniform counter-transform expose a scale jump at the retarget
    // hand-off, where the reading-line content snaps. The frozen bitmap is
    // CSS-scaled into the re-fit box, so the raster stays crisp-at-old-scale
    // without a re-render blink.
    const retainHeldRaster =
      heldOnlyIndexes.has(virtualSlide.index) &&
      existingSlide != null &&
      existingSlide.rasterZoomScale != null &&
      existingSlide.renderKey !== "";
    const rasterZoomScale = retainHeldRaster
      ? existingSlide.rasterZoomScale!
      : zoomScale;
    renderPptxProjectedSlide({
      activity,
      eager,
      layoutZoomScale: zoomScale,
      onSlideRenderTiming,
      projectedSlide,
      priority: getPptxSlideRenderPriority({
        layout,
        scrollDirection,
        scrollTop: metrics.scrollTop,
        viewportHeight: metrics.viewportHeight || viewportHeight,
        virtualSlide,
      }),
      rasterZoomScale,
      renderSlideOverlay,
      rotation,
      source,
      virtualSlide,
    });
    cache.slides.set(virtualSlide.index, projectedSlide);
    placePptxProjectedSlide(
      projectionWindow.content,
      projectedSlide.shell,
      previousShell,
    );
    previousShell = projectedSlide.shell;
  }

  return { fillOverscanNextFrame: fitPerfectly };
}

function unionPptxVirtualSlides(
  windowSlides: PptxVirtualSlide[],
  heldIndexes: number[],
  layout: PptxSlideLayout,
): PptxVirtualSlide[] {
  if (heldIndexes.length === 0) return windowSlides;

  const byIndex = new Map(windowSlides.map((slide) => [slide.index, slide]));
  for (const index of heldIndexes) {
    if (byIndex.has(index)) continue;
    if (index < 0 || index >= layout.slideCount) continue;
    const slideNumber = index + 1;
    byIndex.set(index, {
      height: layout.slideHeight,
      index,
      key: String(slideNumber),
      slideNumber,
      top: getPptxSlideTop(layout, index),
      width: layout.slideWidth,
    });
  }

  return [...byIndex.values()].sort((a, b) => a.index - b.index);
}

function getHeldPptxVirtualSlides(
  heldIndexes: number[],
  layout: PptxSlideLayout,
) {
  return unionPptxVirtualSlides([], heldIndexes, layout);
}

function createPptxProjectedSlide(
  virtualSlide: PptxVirtualSlide,
): PptxProjectedSlide {
  const shell = document.createElement("div");
  shell.className = "absolute top-0 left-1/2";
  shell.dataset.slot = "pptx-slide-slot";
  shell.dataset.virtualSlideNumber = String(virtualSlide.slideNumber);
  // Stable identities so a box-only re-render (target scale commit) does not
  // churn the canvas raster effect, whose key is object-identity sensitive.
  const projectedSlide: PptxProjectedSlide = {
    activity: null,
    getSlideRenderTiming: () => projectedSlide.onSlideRenderTiming ?? undefined,
    isLive: true,
    isProjectedLive: () => projectedSlide.isLive,
    onSlideRenderTiming: null,
    rasterZoomScale: null,
    renderSlideOverlay: null,
    renderKey: "",
    root: createRoot(shell),
    shell,
    source: null,
  };
  return projectedSlide;
}

function patchPptxProjectedSlide(
  shell: HTMLElement,
  virtualSlide: PptxVirtualSlide & { windowTop: number },
) {
  setPptxStyle(
    shell,
    "transform",
    `translate(-50%, ${virtualSlide.windowTop}px)`,
  );
  setPptxPixelStyle(shell, "width", virtualSlide.width);
  setPptxPixelStyle(shell, "height", virtualSlide.height);
}

function placePptxProjectedSlide(
  canvas: HTMLElement,
  shell: HTMLElement,
  previousShell: HTMLElement | null,
) {
  const nextSibling = previousShell
    ? previousShell.nextSibling
    : canvas.firstChild;
  if (shell === nextSibling) return;
  canvas.insertBefore(shell, nextSibling);
}

function setPptxPixelStyle(
  element: HTMLElement,
  property: "height" | "min-width" | "width",
  value: number,
) {
  setPptxStyle(element, property, `${value}px`);
}

function setPptxStyle(element: HTMLElement, property: string, value: string) {
  if (element.style.getPropertyValue(property) === value) return;
  element.style.setProperty(property, value);
}

function ensurePptxProjectionWindow(
  cache: PptxSlideProjectionCache,
  canvas: HTMLDivElement,
): PptxSlideProjectionWindow {
  const existing = cache.window;
  if (existing?.before.parentElement === canvas) return existing;

  const before = document.createElement("div");
  const sticky = document.createElement("div");
  const content = document.createElement("div");
  const after = document.createElement("div");

  before.dataset.slot = "pptx-slide-window-before";
  sticky.dataset.slot = "pptx-slide-sticky-window";
  content.dataset.slot = "pptx-slide-sticky-content";
  after.dataset.slot = "pptx-slide-window-after";

  before.style.contain = "layout size";
  sticky.style.position = "sticky";
  sticky.style.left = "0";
  sticky.style.width = "100%";
  sticky.style.overflow = "visible";
  sticky.style.contain = "layout style inline-size";
  sticky.style.isolation = "isolate";
  sticky.style.display = "flex";
  sticky.style.flexDirection = "column";
  content.style.position = "relative";
  content.style.width = "100%";
  after.style.contain = "layout size";

  sticky.append(content);
  canvas.replaceChildren(before, sticky, after);

  cache.window = { after, before, content, sticky };
  return cache.window;
}

function syncPptxProjectionWindow(
  projectionWindow: PptxSlideProjectionWindow,
  renderedWindow: {
    afterHeight: number;
    beforeHeight: number;
    height: number;
    stickyBottomInset: number;
    stickyTopInset: number;
  },
) {
  setPptxPixelStyle(
    projectionWindow.before,
    "height",
    renderedWindow.beforeHeight,
  );
  setPptxStyle(
    projectionWindow.sticky,
    "top",
    `${renderedWindow.stickyTopInset}px`,
  );
  setPptxStyle(
    projectionWindow.sticky,
    "bottom",
    `${renderedWindow.stickyBottomInset}px`,
  );
  setPptxPixelStyle(projectionWindow.sticky, "height", renderedWindow.height);
  setPptxPixelStyle(projectionWindow.content, "height", renderedWindow.height);
  setPptxPixelStyle(
    projectionWindow.after,
    "height",
    renderedWindow.afterHeight,
  );
}

function renderPptxProjectedSlide({
  activity,
  eager,
  layoutZoomScale,
  onSlideRenderTiming,
  projectedSlide,
  priority,
  rasterZoomScale,
  renderSlideOverlay,
  rotation,
  source,
  virtualSlide,
}: {
  activity: PptxScrollActivity;
  eager: boolean;
  layoutZoomScale: number;
  onSlideRenderTiming?: (timing: PptxSlideRenderTiming) => void;
  projectedSlide: PptxProjectedSlide;
  priority: PptxSlideRenderPriority;
  rasterZoomScale: number;
  renderSlideOverlay?: (props: PptxSlideOverlayProps) => React.ReactNode;
  rotation: number;
  source: PptxSource;
  virtualSlide: PptxVirtualSlide;
}) {
  const renderKey = [
    virtualSlide.index,
    getPptxProjectionSourceKey(source),
    source.baseSize.width,
    source.baseSize.height,
    layoutZoomScale,
    rasterZoomScale,
    rotation,
    eager,
    priority.isCurrentSlide,
    priority.isInViewport,
    priority.isScrollLead,
  ].join("\u0000");
  const shouldRender =
    projectedSlide.renderKey !== renderKey ||
    projectedSlide.source !== source ||
    projectedSlide.activity !== activity ||
    projectedSlide.renderSlideOverlay !== renderSlideOverlay;

  projectedSlide.onSlideRenderTiming = onSlideRenderTiming;
  projectedSlide.rasterZoomScale = rasterZoomScale;

  if (!shouldRender) {
    return;
  }

  projectedSlide.renderKey = renderKey;
  projectedSlide.source = source;
  projectedSlide.activity = activity;
  projectedSlide.renderSlideOverlay = renderSlideOverlay;
  projectedSlide.root.render(
    <PptxSlideFrame
      source={source}
      slideIndex={virtualSlide.index}
      layoutZoomScale={layoutZoomScale}
      rasterZoomScale={rasterZoomScale}
      rotation={rotation}
      eager={eager}
      activity={activity}
      renderSlideOverlay={renderSlideOverlay}
      getSlideRenderTiming={projectedSlide.getSlideRenderTiming}
      isProjectedLive={projectedSlide.isProjectedLive}
      priority={priority}
      shouldRenderImmediately={
        priority.isCurrentSlide ||
        priority.isInViewport ||
        priority.isScrollLead
      }
    />,
  );
}

function getPptxSlideRenderPriority({
  layout,
  scrollDirection,
  scrollTop,
  viewportHeight,
  virtualSlide,
}: {
  layout: PptxSlideLayout;
  scrollDirection: PptxScrollDirection;
  scrollTop: number;
  viewportHeight: number;
  virtualSlide: PptxVirtualSlide;
}): PptxSlideRenderPriority {
  const safeScrollTop =
    Number.isFinite(scrollTop) && scrollTop > 0 ? scrollTop : 0;
  const safeViewportHeight =
    Number.isFinite(viewportHeight) && viewportHeight > 0
      ? viewportHeight
      : layout.slideHeight;
  const marker = safeScrollTop + safeViewportHeight * PPTX_READING_MARKER_RATIO;
  const slideTop = virtualSlide.top;
  const slideBottom = slideTop + virtualSlide.height;
  const viewportBottom = safeScrollTop + safeViewportHeight;
  const isInViewport = slideBottom > safeScrollTop && slideTop < viewportBottom;

  return {
    distanceFromReadingMarker: Math.abs(
      slideTop + virtualSlide.height / 2 - marker,
    ),
    isCurrentSlide: marker >= slideTop && marker < slideBottom,
    isInViewport,
    isScrollLead:
      scrollDirection < 0 &&
      !isInViewport &&
      slideTop < safeScrollTop &&
      slideBottom > safeScrollTop - PPTX_UPWARD_SCROLL_LEAD_PX,
  };
}

function getPptxScrollDirection({
  canMeasureDirection,
  previousScrollTop,
  scrollTop,
}: {
  canMeasureDirection: boolean;
  previousScrollTop: number;
  scrollTop: number;
}): PptxScrollDirection {
  if (!canMeasureDirection) return 0;
  const delta = scrollTop - previousScrollTop;
  if (delta < -1) return -1;
  if (delta > 1) return 1;
  return 0;
}

function disposePptxSlideProjectionCache(cache: PptxSlideProjectionCache) {
  for (const projectedSlide of cache.slides.values()) {
    disposePptxProjectedSlide(projectedSlide);
  }
  cache.slides.clear();
  cache.hasMeasuredScroll = false;
  cache.lastScrollDirection = 0;
  cache.lastScrollTop = 0;
  cache.window?.before.remove();
  cache.window?.sticky.remove();
  cache.window?.after.remove();
  cache.window = null;
}

function shouldFitPptxPerfectly({
  canFitPerfectly,
  previousScrollTop,
  scrollTop,
  viewportHeight,
}: {
  canFitPerfectly: boolean;
  previousScrollTop: number;
  scrollTop: number;
  viewportHeight: number;
}) {
  return (
    canFitPerfectly &&
    viewportHeight > 0 &&
    Math.abs(scrollTop - previousScrollTop) >
      viewportHeight + PPTX_RENDER_WINDOW_OVERSCAN_PX * 2
  );
}

function disposePptxProjectedSlide(projectedSlide: PptxProjectedSlide) {
  projectedSlide.isLive = false;
  deferPptxRootUnmount(projectedSlide.root);
  projectedSlide.shell.remove();
}

function deferPptxRootUnmount(root: Root) {
  const unmount = () => root.unmount();
  if (typeof queueMicrotask === "function") {
    queueMicrotask(unmount);
    return;
  }
  window.setTimeout(unmount, 0);
}

function assignPptxRef<T>(ref: React.Ref<T> | undefined, value: T | null) {
  if (!ref) return;
  if (typeof ref === "function") {
    ref(value);
    return;
  }
  ref.current = value;
}

function getPptxProjectionSourceKey(source: PptxSource) {
  const existingKey = pptxProjectionSourceKeys.get(source);
  if (existingKey) return existingKey;
  const key = nextPptxProjectionSourceKey;
  nextPptxProjectionSourceKey += 1;
  pptxProjectionSourceKeys.set(source, key);
  return key;
}

function PptxSlideOverlay({
  slideNumber,
  visibleSize,
  zoomScale,
  rotation,
  renderSlideOverlay,
}: {
  slideNumber: number;
  visibleSize: PptxSize;
  zoomScale: number;
  rotation: number;
  renderSlideOverlay: (props: PptxSlideOverlayProps) => React.ReactNode;
}) {
  return (
    <div className="pointer-events-none absolute inset-0">
      {renderSlideOverlay({
        slideNumber,
        width: visibleSize.width,
        height: visibleSize.height,
        scale: zoomScale,
        rotation,
      })}
    </div>
  );
}

